  'pages' => 
  array (
    'home' => 
    array (
      'title' => 'Hospitality Academy: സൗദി അറേബ്യയിലെ ഹോട്ടൽ ജീവനക്കാർക്കുള്ള പരിശീലനം',
      'subtitle' => 'റിയാദിലെ Altus Advisory-യിൽ നിന്ന് ഹോട്ടൽ ടീമുകൾക്കായി റോൾ അധിഷ്ഠിത പരിശീലനം, പ്രായോഗിക മൂല്യനിർണയം, സ്ഥിരീകരിക്കാവുന്ന സർട്ടിഫിക്കേഷൻ. അറബിയിലും ഇംഗ്ലീഷിലും നിങ്ങളുടെ ജീവനക്കാർ സംസാരിക്കുന്ന ഭാഷകളിലും.',
      'body' => '<h2>എന്താണ് Hospitality Academy?</h2><p>സൗദി അറേബ്യയിലെ റിയാദ് ആസ്ഥാനമായുള്ള ഹോസ്പിറ്റാലിറ്റി, ബിസിനസ് സ്ട്രാറ്റജി സ്ഥാപനമായ Altus Advisory-യുടെ പൊതു പരിശീലന അക്കാദമിയാണ് Hospitality Academy. ജോലി റോൾ അനുസരിച്ച് ഹോട്ടൽ ജീവനക്കാർക്ക് പരിശീലനം നൽകുകയും ഓരോ വ്യക്തിക്കും യഥാർത്ഥത്തിൽ ജോലി ചെയ്യാനാകുമോ എന്ന് പരിശോധിക്കുകയും ചെയ്യുന്ന altus Hospitality Knowledge &amp; Performance പ്ലാറ്റ്ഫോമിലാണ് ഇത് പ്രവർത്തിക്കുന്നത്.</p><h2>സാധാരണ ഓൺലൈൻ കോഴ്സിൽ നിന്ന് ഇത് എങ്ങനെ വ്യത്യസ്തമാണ്?</h2><p>പൂർത്തീകരണം തെളിവായി കണക്കാക്കുന്നില്ല. ഓരോ പഠിതാവും റോൾ അധിഷ്ഠിത പഠനത്തിൽ നിന്ന് തിയറി, പ്രായോഗിക മൂല്യനിർണയത്തിലേക്ക് നീങ്ങുന്നു, ഫലം നിർവചിക്കപ്പെട്ട കഴിവുകൾക്കനുസരിച്ച് രേഖപ്പെടുത്തുന്നു. ഒരു വിടവ് കണ്ടെത്തിയാൽ, ഒരു പ്രവർത്തന പദ്ധതിയും പുനർമൂല്യനിർണയവും തുടർന്ന് വരുന്നു, അതിനാൽ മാനേജർമാർ പൂർത്തിയാക്കിയ വീഡിയോകളുടെ പട്ടികയല്ല, കഴിവിന്റെ തെളിവാണ് കാണുന്നത്.</p><ol><li>ജോലി റോളിന്റെ ആവശ്യകതകളിൽ നിന്ന് നൽകുന്ന പഠനം</li><li>ഒരേ മാനദണ്ഡത്തിൽ തിയറി മൂല്യനിർണയവും പ്രായോഗിക മൂല്യനിർണയവും</li><li>കഴിവ് രേഖ, കണ്ടെത്തിയ വിടവുകൾ, തിരുത്തൽ പ്രവർത്തന പദ്ധതി</li><li>പുനർമൂല്യനിർണയം, തയ്യാറെടുപ്പ് നില, സ്ഥിരീകരിക്കാവുന്ന സർട്ടിഫിക്കറ്റ്</li></ol><h2>അക്കാദമി ഏതൊക്കെ ഹോട്ടൽ വകുപ്പുകൾ ഉൾക്കൊള്ളുന്നു?</h2><p>മാസ്റ്റർ പാഠ്യപദ്ധതി പത്ത് പ്രധാന പ്രൊഫഷണൽ മേഖലകളായി ക്രമീകരിച്ചിരിക്കുന്നു: ഹോട്ടൽ അടിസ്ഥാനങ്ങൾ, ഫ്രണ്ട് ഓഫീസ്, ഹൗസ്‌കീപ്പിംഗ്, ഫുഡ് ആൻഡ് ബിവറേജ്, അടുക്കള, സെയിൽസ് ആൻഡ് മാർക്കറ്റിംഗ്, റവന്യൂ ആൻഡ് റിസർവേഷൻസ്, ഗസ്റ്റ് എക്സ്പീരിയൻസ്, ഗുണനിലവാരവും ഓഡിറ്റും, സെക്യൂരിറ്റിയും സുരക്ഷയും. <a href="/en/courses">കോഴ്സ് കാറ്റലോഗ്</a> ബ്രൗസ് ചെയ്യുക, അല്ലെങ്കിൽ ഒരു പ്രത്യേക റോളിനായി ഘടനാപരമായ <a href="/en/learning-paths">പഠന പാത</a> പിന്തുടരുക.</p><h2>ഹോട്ടൽ ജീവനക്കാർക്ക് ഏതൊക്കെ ഭാഷകളിൽ പഠിക്കാം?</h2><p>അറബിയും ഇംഗ്ലീഷും ഒരൊറ്റ അനുഭവമായി ഉൾച്ചേർത്തിരിക്കുന്നു, അറബി വലത്തുനിന്ന് ഇടത്തോട്ടുള്ള ക്രമീകരണത്തിൽ. സ്റ്റാഫ് വർക്ക്‌സ്പേസ് ഹിന്ദി, ഉറുദു, ഫിലിപ്പിനോ, ബംഗാളി, നേപ്പാളി, മലയാളം എന്നിവയെയും പിന്തുണയ്ക്കുന്നു, അതിനാൽ ഓരോ ഷിഫ്റ്റിലും മാനദണ്ഡം നടപ്പാക്കുന്ന ആളുകൾക്ക് അത് മനസ്സിലാകുന്നു.</p><h2>ഒരു തൊഴിലുടമയ്ക്ക് സർട്ടിഫിക്കറ്റ് പരിശോധിക്കാനാകുമോ?</h2><p>ഉവ്വ്. ഓരോ സർട്ടിഫിക്കറ്റിനും ഒരു അദ്വിതീയ നമ്പറും സ്ഥിരീകരണ കോഡും ഉണ്ട്, അത് സാധുവാണോ, കാലാവധി കഴിഞ്ഞതാണോ, റദ്ദാക്കിയതാണോ എന്ന് <a href="/en/verify">സർട്ടിഫിക്കറ്റ് സ്ഥിരീകരണ പേജിൽ</a> ആർക്കും ഉറപ്പാക്കാം.</p><h2>അക്കാദമി Vision 2030-നെ എങ്ങനെ പിന്തുണയ്ക്കുന്നു?</h2><p>2030-ഓടെ രാജ്യത്തേക്ക് പ്രതിവർഷം 150 ദശലക്ഷം സന്ദർശനങ്ങൾ Vision 2030 ലക്ഷ്യമിടുന്നു, ആ വളർച്ചയുടെ കേന്ദ്രത്തിൽ സൗദി മാനവ മൂലധനത്തെ സ്ഥാപിക്കുന്നു. ദ്വിഭാഷാ പഠന പാതകൾ, മൂല്യനിർണയം ചെയ്ത കഴിവ്, സൗദി അറേബ്യയിലെയും GCC-യിലെയും ഹോട്ടലുകൾക്ക് ആശ്രയിക്കാവുന്ന സർട്ടിഫിക്കേഷൻ എന്നിവയിലൂടെ Altus Advisory അക്കാദമിയെ ആ ലക്ഷ്യങ്ങളുമായി യോജിപ്പിക്കുന്നു.</p><p>ഹോട്ടൽ ഉടമകൾക്കും ഓപ്പറേറ്റർമാർക്കും <a href="/en/hotels">തങ്ങളുടെ പ്രോപ്പർട്ടികൾക്കായി പരിശീലനം ക്രമീകരിക്കാം</a> അല്ലെങ്കിൽ <a href="/en/contact">റിയാദിലെ അക്കാദമി ടീമുമായി സംസാരിക്കാം</a>.</p>',
      'cta_label' => 'കോഴ്സ് കാറ്റലോഗ് ബ്രൗസ് ചെയ്യുക',
      'meta_title' => 'സൗദി അറേബ്യയിലെ ഹോട്ടൽ സ്റ്റാഫ് പരിശീലനം | Hospitality Academy',
      'meta_description' => 'Altus Advisory-യുടെ സൗദി ഹോട്ടൽ സ്റ്റാഫ് പരിശീലനം: റോൾ അധിഷ്ഠിത പഠനം, പ്രായോഗിക മൂല്യനിർണയം, അറബിയിലും ഇംഗ്ലീഷിലും സ്ഥിരീകരിക്കാവുന്ന സർട്ടിഫിക്കറ്റുകൾ.',
      'focus_keyword' => 'സൗദി അറേബ്യയിലെ ഹോട്ടൽ സ്റ്റാഫ് പരിശീലനം',
    ),
    'about' => 
    array (
      'title' => 'Hospitality Academy-യെക്കുറിച്ച്',
      'subtitle' => 'റിയാദിലെ Altus Advisory-യുടെ പൊതു പരിശീലന അക്കാദമി: ഉള്ളടക്കത്തിന് പിന്നിൽ ആരാണ്, അത് എങ്ങനെ അംഗീകരിക്കപ്പെടുന്നു, ഞങ്ങൾ എന്ത് അവകാശപ്പെടും, എന്ത് അവകാശപ്പെടില്ല.',
      'body' => '<h2>Hospitality Academy നടത്തുന്നത് ആരാണ്?</h2><p>സൗദി അറേബ്യ രാജ്യത്തെ റിയാദ് ആസ്ഥാനമായി, GCC, MENA മേഖലകളിലുടനീളമുള്ള ക്ലയന്റുകൾക്ക് സേവനം നൽകുന്ന ബൂട്ടിക് സ്ട്രാറ്റജി സ്ഥാപനമായ Altus Advisory ആണ് Hospitality Academy പ്രവർത്തിപ്പിക്കുന്നത്. Hospitality Solutions, Business Growth Solutions എന്നീ രണ്ട് സംയോജിത വിഭാഗങ്ങളിലൂടെയാണ് Altus പ്രവർത്തിക്കുന്നത്, അതിന്റെ പ്രവർത്തന മാനദണ്ഡങ്ങൾ ഹോട്ടൽ ടീമുകളിലേക്ക് നേരിട്ട് എത്തുന്നത് അക്കാദമിയിലൂടെയാണ്.</p><h2>പരിശീലന ഉള്ളടക്കം ഏത് അനുഭവത്തെ അടിസ്ഥാനമാക്കിയുള്ളതാണ്?</h2><p>Marriott, IHG, Starwood, Accor സംവിധാനങ്ങൾക്കുള്ളിലും സ്വതന്ത്ര ഹോട്ടലുകളിലും നേടിയ, ആകെ 60 വർഷത്തിലധികം നേതൃത്വ പരിചയമുള്ള Altus സ്ഥാപകരുടെ പ്രവർത്തന മാനദണ്ഡങ്ങളിൽ നിന്നാണ് ഉള്ളടക്കം രൂപപ്പെടുത്തിയിരിക്കുന്നത്. പരിശീലനം ആരംഭിക്കുന്നത് ഒരു പൊതു കോഴ്സ് ലൈബ്രറിയിൽ നിന്നല്ല, ഷിഫ്റ്റിൽ നിർവഹിക്കുന്ന രീതിയിലുള്ള സ്റ്റാൻഡേർഡ് ഓപ്പറേറ്റിംഗ് പ്രൊസീജറുകളിൽ നിന്നാണ്.</p><h2>അക്കാദമിക്ക് altus പ്ലാറ്റ്ഫോമുമായുള്ള ബന്ധം എന്താണ്?</h2><p>altus Hospitality Knowledge &amp; Performance പ്ലാറ്റ്ഫോമിലേക്കുള്ള പൊതു പ്രവേശന കവാടമാണ് അക്കാദമി. പ്ലാറ്റ്ഫോമിനുള്ളിൽ, ഹോട്ടലുകൾ റോൾ അനുസരിച്ച് പഠനം നൽകുന്നു, തിയറി, പ്രായോഗിക മൂല്യനിർണയങ്ങൾ നടത്തുന്നു, കഴിവ് വിടവുകളും പ്രവർത്തന പദ്ധതികളും ട്രാക്ക് ചെയ്യുന്നു, ഓരോ ജീവനക്കാരന്റെയും തയ്യാറെടുപ്പ് കാണുന്നു. നിയന്ത്രിതമായ ഒരു AI അസിസ്റ്റന്റ് അംഗീകൃത ഉള്ളടക്കത്തിൽ നിന്ന് മാത്രം ജീവനക്കാരുടെ ചോദ്യങ്ങൾക്ക് ഉത്തരം നൽകുന്നു, ആ ഉള്ളടക്കം ഒരു ചോദ്യം ഉൾക്കൊള്ളുന്നില്ലെങ്കിൽ അത് വ്യക്തമാക്കുകയും ചെയ്യുന്നു.</p><h2>പരിശീലന ഉള്ളടക്കം എങ്ങനെ അംഗീകരിക്കപ്പെടുന്നു?</h2><p>ഓരോ പാഠവും നടപടിക്രമവും മൂല്യനിർണയവും പഠിതാക്കൾ കാണുന്നതിന് മുമ്പ് നിയന്ത്രിതമായ അവലോകനത്തിലൂടെ കടന്നുപോകുന്നു.</p><ol><li>രചയിതാവ് ഒരു കരട് തയ്യാറാക്കുന്നു.</li><li>കരടിന് ആന്തരിക അംഗീകാരം ലഭിക്കുന്നു.</li><li>കരടിന് ഗുണനിലവാര അംഗീകാരം ലഭിക്കുന്നു.</li><li>ഉള്ളടക്കം പ്രസിദ്ധീകരിക്കുകയും അതിന്റെ പതിപ്പ് രേഖപ്പെടുത്തുകയും ചെയ്യുന്നു.</li></ol><p>രചയിതാക്കൾക്ക് സ്വന്തം ജോലി അംഗീകരിക്കാനാവില്ല, മുൻ പതിപ്പുകൾ രേഖയിൽ തുടരുന്നു, അതിനാൽ ഏത് തീയതിയിലും ഏത് മാനദണ്ഡമാണ് ബാധകമായിരുന്നതെന്ന് ഒരു ഓഡിറ്റർക്ക് കാണാനാകും.</p><h2>അക്കാദമിയെ നയിക്കുന്ന തത്വങ്ങൾ എന്തൊക്കെ?</h2><p>Altus Advisory ഓരോ ദൗത്യത്തിലും പ്രയോഗിക്കുന്ന തത്വങ്ങൾ അക്കാദമി പിന്തുടരുന്നു.</p><ul><li>സഹജബോധത്തേക്കാൾ തെളിവ്: കഴിവ് ഹാജരിൽ നിന്ന് അനുമാനിക്കുന്നില്ല, മൂല്യനിർണയത്തിലൂടെ തെളിയിക്കുന്നു.</li><li>അറബിയിലും ഇംഗ്ലീഷിലും ഹോട്ടൽ ജീവനക്കാർ ഉപയോഗിക്കുന്ന തൊഴിൽസേനാ ഭാഷകളിലും ഓരോ ഷിഫ്റ്റിലും നിലനിൽക്കുന്ന മാനദണ്ഡങ്ങൾ.</li><li>ദൗത്യത്തിനപ്പുറമുള്ള പങ്കാളിത്തം: ഇടപെടൽ അവസാനിച്ചതിന് ശേഷവും അറിവ് ക്ലയന്റ് സ്ഥാപനത്തിനുള്ളിൽ നിലനിൽക്കുന്നു.</li><li>സൗദിവൽക്കരണം, യുവജന ശാക്തീകരണം എന്നിവയ്ക്കുള്ള Vision 2030 ലക്ഷ്യങ്ങൾക്കനുസൃതമായി സൗദി മാനവ മൂലധനത്തിനുള്ള പിന്തുണ.</li></ul><h2>അക്കാദമി എന്താണ് അവകാശപ്പെടാത്തത്?</h2><p>ഈ സൈറ്റ് വിജയ നിരക്കുകളോ ക്ലയന്റ് അംഗീകാരങ്ങളോ അക്രഡിറ്റേഷൻ അവകാശവാദങ്ങളോ പ്രസിദ്ധീകരിക്കുന്നില്ല. ഒരു സർട്ടിഫിക്കറ്റ് അത് രേഖപ്പെടുത്തുന്നത് കൃത്യമായി പ്രസ്താവിക്കുന്നു: ആര് ഏത് കോഴ്സ് അല്ലെങ്കിൽ പ്രോഗ്രാം പൂർത്തിയാക്കി, ഏത് തീയതിയിൽ, എന്ത് ഫലത്തോടെ, അത് ഇപ്പോഴും സാധുവാണോ എന്ന്. <a href="/en/certificates">സർട്ടിഫിക്കേഷൻ എങ്ങനെ പ്രവർത്തിക്കുന്നു</a> എന്ന് വായിക്കുക, അല്ലെങ്കിൽ <a href="/en/altus">Altus Advisory-യെയും അതിന്റെ സേവനങ്ങളെയും</a> കുറിച്ച് കൂടുതലറിയുക.</p>',
      'cta_label' => 'സർട്ടിഫിക്കേഷൻ എങ്ങനെ പ്രവർത്തിക്കുന്നുവെന്ന് കാണുക',
      'meta_title' => 'റിയാദിലെ ഹോസ്പിറ്റാലിറ്റി പരിശീലന അക്കാദമി | Altus Advisory',
      'meta_description' => 'ഓപ്പറേറ്റർ നിലവാര മാനദണ്ഡങ്ങളിലും നിയന്ത്രിത അവലോകനത്തിലും നിർമ്മിച്ച, Altus Advisory-യുടെ റിയാദ് ആസ്ഥാനമായ ഹോസ്പിറ്റാലിറ്റി പരിശീലന അക്കാദമിയാണ് Hospitality Academy.',
      'focus_keyword' => 'റിയാദിലെ ഹോസ്പിറ്റാലിറ്റി പരിശീലന അക്കാദമി',
    ),
    'for-hotels' => 
    array (
      'title' => 'സൗദി അറേബ്യയിലെ പ്രോപ്പർട്ടികൾക്കുള്ള ഹോട്ടൽ പരിശീലന പ്ലാറ്റ്ഫോം',
      'subtitle' => 'റോൾ അനുസരിച്ച് പഠനം നൽകുക, തിയറിയും പ്രായോഗികവും വിലയിരുത്തുക, കഴിവ് വിടവുകൾ നികത്തുക, ഓരോ പ്രോപ്പർട്ടിയുടെയും തയ്യാറെടുപ്പ് കാണുക, ഒരൊറ്റ ദ്വിഭാഷാ വർക്ക്‌സ്പേസിൽ.',
      'body' => '<h2>ഹോട്ടലുകൾക്ക് കോഴ്സ് പൂർത്തീകരണം മാത്രമല്ല, കഴിവിന്റെ തെളിവ് ആവശ്യമാകുന്നത് എന്തുകൊണ്ട്?</h2><p>തങ്ങളുടെ ടീമുകൾ എന്ത് ചെയ്യണമെന്ന് മിക്ക ഹോട്ടലുകൾക്കും ഇതിനകം അറിയാം. ഓരോ വ്യക്തിക്കും നിലവിലെ മാനദണ്ഡത്തിൽ അത് ചെയ്യാനാകുമെന്ന് തെളിയിക്കുന്നതും, ഒരു അതിഥിയോ ഓഡിറ്റോ പരിശോധനയോ കണ്ടെത്തുന്നതിന് മുമ്പ് വിടവുകൾ കണ്ടെത്തുന്നതുമാണ് ബുദ്ധിമുട്ട്. റിയാദിലെയും സൗദി അറേബ്യയിലുടനീളവുമുള്ള ഹോട്ടലുകൾക്കായി ആ വിടവ് നികത്താനാണ് Altus Advisory altus Hospitality Knowledge &amp; Performance പ്ലാറ്റ്ഫോം നിർമ്മിച്ചത്.</p><h2>പ്ലാറ്റ്ഫോമിൽ നിന്ന് ഒരു ഹോട്ടലിന് എന്ത് ലഭിക്കുന്നു?</h2><p>ഓരോ പ്രോപ്പർട്ടിക്കും പരിശീലനവും മൂല്യനിർണയവും തെളിവും ഒരുമിച്ചുള്ള ഒരൊറ്റ വർക്ക്‌സ്പേസ്.</p><ul><li>വ്യക്തികൾ, ജോലി റോളുകൾ, വകുപ്പുകൾ അല്ലെങ്കിൽ കൂട്ടങ്ങൾക്ക് പൂർത്തീകരണ തീയതികളും ഇളവുകളും സഹിതം നൽകുന്ന പഠനം</li><li>വെയ്റ്റഡ് റൂബ്രിക്കുകളിൽ സ്കോർ ചെയ്യുന്ന തിയറി, പ്രായോഗിക മൂല്യനിർണയങ്ങൾ, ഒരു നിർണായക മാനദണ്ഡം ഫലത്തിന് പരിധി നിശ്ചയിക്കുന്നു</li><li>കഴിവ് പ്രൊഫൈലുകൾ, ഗ്യാപ് ഹീറ്റ്മാപ്പ്, തെളിവ് അപ്‌ലോഡ് സഹിതമുള്ള പ്രവർത്തന പദ്ധതികൾ, പുനർമൂല്യനിർണയം</li><li>പ്രീ-ഓപ്പണിംഗ് ടീമുകൾക്കുള്ള ഓപ്പണിംഗ് തയ്യാറെടുപ്പ് ഉൾപ്പെടെ, ഓരോ ജീവനക്കാരന്റെയും തയ്യാറെടുപ്പ് നില</li><li>CSV, XLSX എന്നിവയിലേക്ക് എക്സ്പോർട്ട് ചെയ്യുന്ന ഗുണനിലവാര ഓഡിറ്റുകൾ, KPI-കൾ, റിപ്പോർട്ടുകൾ</li><li>നിങ്ങളുടെ അംഗീകൃത SOP-കളിൽ നിന്നും നയങ്ങളിൽ നിന്നും മാത്രം, ഉറവിടങ്ങൾ സഹിതം ഉത്തരം നൽകുന്ന നിയന്ത്രിതമായ AI അസിസ്റ്റന്റ്</li><li>പ്രോപ്പർട്ടി ബ്രാൻഡിംഗ്: നിങ്ങളുടെ ലോഗോ, നിറങ്ങൾ, പേര്</li></ul><h2>പ്ലാറ്റ്ഫോമിനുള്ളിൽ ആര് എന്ത് കാണുന്നു?</h2><p>പ്രവേശനം നിങ്ങളുടെ സ്ഥാപന ഘടനയെ പിന്തുടരുന്നു. ഒരു വകുപ്പ് മേധാവി തന്റെ ടീമിനെ കാണുന്നു, ജനറൽ മാനേജർ പ്രോപ്പർട്ടി കാണുന്നു, ഒരു എക്സിക്യൂട്ടീവ് പോർട്ട്ഫോളിയോ അവലോകനവും അച്ചടിക്കാവുന്ന ബോർഡ് റിപ്പോർട്ടും കാണുന്നു. ഓരോ ഘട്ടവും നിങ്ങളുടെ സ്ഥാപനത്തിൽ പരിമിതപ്പെടുത്തുകയും ഓഡിറ്റ് ലോഗിൽ രേഖപ്പെടുത്തുകയും ചെയ്യുന്നു, ഒരു സ്ഥാപനത്തിനും മറ്റൊരു സ്ഥാപനത്തിന്റെ ഡാറ്റ കാണാനാവില്ല.</p><h2>പ്ലാറ്റ്ഫോം ഏതൊക്കെ പ്രോപ്പർട്ടികൾക്കായി രൂപകൽപ്പന ചെയ്തിരിക്കുന്നു?</h2><p>Altus Advisory കോർപ്പറേറ്റ് പ്രൊഫൈൽ അനുസരിച്ച്, ആഗോള ശൃംഖല സംവിധാനങ്ങളുടെ ചെലവും സങ്കീർണ്ണതയും ഇല്ലാതെ പ്രായോഗികവും മാനദണ്ഡാധിഷ്ഠിതവുമായ പരിശീലനം ആവശ്യമുള്ള, സൗദി അറേബ്യയിലെയും അറബ് മേഖലയിലെയും സ്വതന്ത്ര ഹോട്ടലുകൾ, സർവീസ്ഡ് അപ്പാർട്ട്മെന്റുകൾ, SME സ്ഥാപനങ്ങൾ എന്നിവയ്ക്കായി പ്രത്യേകം നിർമ്മിച്ചതാണ് ഈ പ്ലാറ്റ്ഫോം. ആവശ്യം വർദ്ധിക്കുകയാണ്: സൗദി ടൂറിസം മന്ത്രാലയത്തിന്റെ പ്രാഥമിക ഡാറ്റ 2025-ൽ 122 ദശലക്ഷം ആഭ്യന്തര, അന്തർദേശീയ സന്ദർശനങ്ങൾ രേഖപ്പെടുത്തുന്നു, Vision 2030 2030-ഓടെ പ്രതിവർഷം 150 ദശലക്ഷം സന്ദർശനങ്ങൾ ലക്ഷ്യമിടുന്നു.</p><h2>ഞങ്ങൾ എങ്ങനെ ആരംഭിക്കും?</h2><p>ക്രമീകരണം ആരംഭിക്കുന്നത് ഒരു ശൂന്യ കാറ്റലോഗിൽ നിന്നല്ല, നിങ്ങളുടെ ഘടനയിൽ നിന്നാണ്.</p><ol><li>നിങ്ങളുടെ പ്രോപ്പർട്ടികൾ, വകുപ്പുകൾ, ഓരോ വകുപ്പിലെയും ഏകദേശ ജീവനക്കാരുടെ എണ്ണം എന്നിവ പങ്കിടുക.</li><li>Altus സ്ഥാപനം ക്രമീകരിക്കുകയും ജോലി റോളുകളെ അവയ്ക്ക് ആവശ്യമായ കഴിവുകളുമായി ബന്ധിപ്പിക്കുകയും ചെയ്യുന്നു.</li><li>നിർബന്ധിത പരിശീലനം നൽകുന്നു, അതിനാൽ ജീവനക്കാർ ആദ്യ ലോഗിനിൽ തന്നെ അവരുടെ പട്ടിക തുറക്കുന്നു.</li><li>മാനേജർമാർ അവരുടെ ഡാഷ്ബോർഡിൽ നിന്ന് പൂർത്തീകരണം, മൂല്യനിർണയ ഫലങ്ങൾ, തയ്യാറെടുപ്പ് എന്നിവ പിന്തുടരുന്നു.</li></ol><p><a href="/en/hotels/training">വകുപ്പ് അനുസരിച്ചുള്ള പരിശീലന പരിപാടികൾ</a> കാണുക, <a href="/en/programs">സർട്ടിഫിക്കേഷൻ പ്രോഗ്രാമുകൾ</a> ബ്രൗസ് ചെയ്യുക, അല്ലെങ്കിൽ <a href="/en/contact">അക്കാദമി ടീമുമായി സംസാരിക്കുക</a>.</p>',
      'cta_label' => 'അക്കാദമിയുമായി സംസാരിക്കുക',
      'meta_title' => 'സൗദി അറേബ്യയിലെ ഹോട്ടൽ പരിശീലന പ്ലാറ്റ്ഫോം | Altus Advisory',
      'meta_description' => 'സൗദി അറേബ്യയ്ക്കുള്ള ഹോട്ടൽ പരിശീലന പ്ലാറ്റ്ഫോം: റോൾ അനുസരിച്ച് പഠനം, പ്രായോഗിക മൂല്യനിർണയം, കഴിവ് വിടവുകൾ നികത്തൽ, ഓരോ പ്രോപ്പർട്ടിയുടെയും തയ്യാറെടുപ്പ്.',
      'focus_keyword' => 'സൗദി അറേബ്യയിലെ ഹോട്ടൽ പരിശീലന പ്ലാറ്റ്ഫോം',
    ),
    'hotels-training' => 
    array (
      'title' => 'വകുപ്പ് അനുസരിച്ചുള്ള ഹോട്ടൽ സ്റ്റാഫ് പരിശീലന പരിപാടികൾ',
      'subtitle' => 'ഓരോ ഹോട്ടൽ വകുപ്പിനും എന്തിലാണ് പരിശീലനം, അത് നൽകുന്ന ക്രമം, ഒരു ജീവനക്കാരൻ മേൽനോട്ടമില്ലാതെ ജോലി ചെയ്യുന്നതിന് മുമ്പ് കഴിവ് എങ്ങനെ സ്ഥിരീകരിക്കുന്നു.',
      'body' => '<h2>ഓരോ ഹോട്ടൽ വകുപ്പിനും എന്ത് പരിശീലനമാണ് വേണ്ടത്?</h2><p>ഫീൽഡിൽ പരീക്ഷിച്ച പ്രവർത്തന മാനദണ്ഡങ്ങളിൽ നിന്ന് റിയാദിൽ Altus Advisory വികസിപ്പിച്ച മാസ്റ്റർ പാഠ്യപദ്ധതിക്കുള്ളിൽ ഓരോ വകുപ്പും സ്വന്തം ട്രാക്ക് പിന്തുടരുന്നു. ഉള്ളടക്കം പ്രൊഫഷണൽ മേഖല, ട്രാക്ക്, മൊഡ്യൂൾ, പാഠം എന്നിങ്ങനെ ഘടനപ്പെടുത്തിയിരിക്കുന്നു, തുടർന്ന് മൂല്യനിർണയവും സർട്ടിഫിക്കേഷനും, അതിനാൽ ഓരോ റോളിനും നിർവചിക്കപ്പെട്ട ഒരു പാതയുണ്ട്.</p><ul><li><strong>ഫ്രണ്ട് ഓഫീസ്:</strong> വരവും പുറപ്പെടലും, അതിഥി രജിസ്ട്രേഷനും സ്വകാര്യതയും, റൂം അസൈൻമെന്റ്, പരാതി കൈകാര്യം ചെയ്യൽ, അപ്‌സെല്ലിംഗ്, നൈറ്റ് ഓഡിറ്റ്.</li><li><strong>ഹൗസ്‌കീപ്പിംഗ്:</strong> മുറി വൃത്തിയാക്കൽ ക്രമം, കിടക്ക, ബാത്ത്റൂം മാനദണ്ഡങ്ങൾ, രാസവസ്തു സുരക്ഷ, ലോസ്റ്റ് ആൻഡ് ഫൗണ്ട്, ലോൺഡ്രി, പൊതു ഇടങ്ങൾ, പരിശോധന.</li><li><strong>ഫുഡ് ആൻഡ് ബിവറേജ്:</strong> സേവന ക്രമം, സ്വാഗതവും ഇരിപ്പിടവും, ടേബിൾ, പാനീയ സേവനം, ബാങ്ക്വറ്റുകൾ, പോയിന്റ് ഓഫ് സെയിൽ നടപടിക്രമം.</li><li><strong>അടുക്കള:</strong> ഭക്ഷ്യസുരക്ഷ, താപനില നിയന്ത്രണം, സംഭരണവും സ്വീകരണവും, അലർജൻ കൈകാര്യം ചെയ്യൽ, കത്തി സുരക്ഷ, മാലിന്യ നിയന്ത്രണം.</li><li><strong>സെയിൽസ്, റവന്യൂ, റിസർവേഷൻസ്:</strong> സെയിൽസ് ആൻഡ് മാർക്കറ്റിംഗ്, റിസർവേഷൻ നടപടിക്രമം, വിതരണം, റവന്യൂ അടിസ്ഥാനങ്ങൾ.</li><li><strong>ഗസ്റ്റ് എക്സ്പീരിയൻസ്, ഗുണനിലവാരം, ഓഡിറ്റ്:</strong> സർവീസ് റിക്കവറി, ബ്രാൻഡ്, SOP അനുസരണം, ഗുണനിലവാര പരിശോധന.</li><li><strong>സെക്യൂരിറ്റിയും സുരക്ഷയും:</strong> ഓരോ ജീവനക്കാരനും അഗ്നി സുരക്ഷ, അടിയന്തര പ്രതികരണം, സെക്യൂരിറ്റി നടപടിക്രമം.</li></ul><h2>ഹോട്ടൽ സ്റ്റാഫ് പരിശീലനം ഏത് ക്രമത്തിലാണ് നൽകുന്നത്?</h2><p>ആദ്യം സുരക്ഷയും അടിസ്ഥാനങ്ങളും, തുടർന്ന് റോൾ കഴിവുകൾ, പിന്നെ അതേ മാനദണ്ഡത്തിന്റെ മൂല്യനിർണയം.</p><ol><li>ഓരോ ജീവനക്കാരനും ഹോട്ടൽ അടിസ്ഥാനങ്ങൾ, പ്രോപ്പർട്ടി ഇൻഡക്ഷൻ, സുരക്ഷ</li><li>ഹൗസ്‌കീപ്പിംഗിലെ രാസവസ്തു സുരക്ഷ അല്ലെങ്കിൽ അടുക്കളയിലെ ഭക്ഷ്യസുരക്ഷയും അലർജൻ കൈകാര്യം ചെയ്യലും പോലുള്ള റോൾ മുൻവ്യവസ്ഥകൾ</li><li>വീഡിയോ, PDF, സ്ലൈഡുകൾ അല്ലെങ്കിൽ ഓഡിയോ രൂപത്തിൽ ചെറിയ പ്രായോഗിക പാഠങ്ങളുള്ള റോൾ മൊഡ്യൂളുകൾ</li><li>ഒരു തിയറി മൂല്യനിർണയം, തുടർന്ന് ഒരു സൂപ്പർവൈസറുടെ പ്രായോഗിക മൂല്യനിർണയം</li><li>ഒരു സർട്ടിഫിക്കറ്റ്, അല്ലെങ്കിൽ വിടവ് കണ്ടെത്തിയാൽ ഒരു പ്രവർത്തന പദ്ധതിയും പുനർമൂല്യനിർണയവും</li></ol><h2>പരിശീലനത്തിന് ഞങ്ങളുടെ സ്വന്തം ഹോട്ടൽ മാനദണ്ഡങ്ങൾ പിന്തുടരാനാകുമോ?</h2><p>ഉവ്വ്. പ്ലാറ്റ്ഫോം ഓരോ പ്രോപ്പർട്ടിക്കും വൈറ്റ്-ലേബലാണ്, നിങ്ങളുടെ അംഗീകൃത SOP-കൾ, നയങ്ങൾ, ചെക്ക്‌ലിസ്റ്റുകൾ എന്നിവ പാഠ്യപദ്ധതിക്കൊപ്പം നിലനിൽക്കുന്നു, ഓരോ പതിപ്പിനും ജീവനക്കാരുടെ അംഗീകാരം രേഖപ്പെടുത്തുന്നു. AI അസിസ്റ്റന്റ് ആ അംഗീകൃത ഉള്ളടക്കത്തിൽ നിന്ന് മാത്രം ജീവനക്കാരുടെ ചോദ്യങ്ങൾക്ക് ഉത്തരം നൽകുന്നു.</p><h2>അറബിയോ ഇംഗ്ലീഷോ വായിക്കാത്ത ജീവനക്കാർക്ക് പരിശീലനം ലഭ്യമാണോ?</h2><p>പാഠങ്ങൾ അറബിയിലും ഇംഗ്ലീഷിലും ദ്വിഭാഷയാണ്, സൗദി അറേബ്യയിലുടനീളമുള്ള ഹോട്ടലുകളിൽ ജോലി ചെയ്യുന്ന ബഹുരാഷ്ട്ര ടീമുകൾക്കായി സ്റ്റാഫ് വർക്ക്‌സ്പേസ് ഹിന്ദി, ഉറുദു, ഫിലിപ്പിനോ, ബംഗാളി, നേപ്പാളി, മലയാളം എന്നിവയെയും പിന്തുണയ്ക്കുന്നു.</p><p><a href="/en/courses">പൂർണ കോഴ്സ് കാറ്റലോഗ്</a> പര്യവേക്ഷണം ചെയ്യുക, <a href="/en/learning-paths">റോൾ അനുസരിച്ചുള്ള പഠന പാത</a> പിന്തുടരുക, അല്ലെങ്കിൽ <a href="/en/hotels">ഹോട്ടലുകൾ പ്ലാറ്റ്ഫോം എങ്ങനെ വിന്യസിക്കുന്നു</a> എന്ന് വായിക്കുക.</p>',
      'cta_label' => 'പൂർണ കാറ്റലോഗ് കാണുക',
      'meta_title' => 'വകുപ്പ് അനുസരിച്ചുള്ള ഹോട്ടൽ സ്റ്റാഫ് പരിശീലന പരിപാടികൾ | KSA',
      'meta_description' => 'ഫ്രണ്ട് ഓഫീസ് മുതൽ അടുക്കള വരെ, സൗദി അറേബ്യയിലെ ടീമുകൾക്ക് പ്രായോഗിക മൂല്യനിർണയവും സർട്ടിഫിക്കേഷനും സഹിതം വകുപ്പ് അനുസരിച്ചുള്ള ഹോട്ടൽ സ്റ്റാഫ് പരിശീലനം.',
      'focus_keyword' => 'ഹോട്ടൽ സ്റ്റാഫ് പരിശീലന പരിപാടികൾ',
    ),
    'certificates-info' => 
    array (
      'title' => 'ഹോട്ടൽ പരിശീലന സർട്ടിഫിക്കറ്റുകളും സ്ഥിരീകരണവും',
      'subtitle' => 'ഒരു Hospitality Academy സർട്ടിഫിക്കറ്റ് എന്ത് രേഖപ്പെടുത്തുന്നു, അത് എപ്പോൾ നൽകുന്നു, അത് യഥാർത്ഥവും നിലവിലുള്ളതുമാണോ എന്ന് ഒരു തൊഴിലുടമയ്ക്ക് നിമിഷങ്ങൾക്കുള്ളിൽ എങ്ങനെ പരിശോധിക്കാം.',
      'body' => '<h2>Hospitality Academy സർട്ടിഫിക്കറ്റ് എപ്പോഴാണ് നൽകുന്നത്?</h2><p>ഒരു പഠിതാവ് ഒരു കോഴ്സിലെ എല്ലാ നിർബന്ധിത പാഠങ്ങളും പൂർത്തിയാക്കി, ആ കോഴ്സിന് നിശ്ചയിച്ച വിജയ മാർക്കിലോ അതിന് മുകളിലോ മൂല്യനിർണയം വിജയിക്കുമ്പോഴാണ് സർട്ടിഫിക്കറ്റ് നൽകുന്നത്. പ്രോഗ്രാമിലെ എല്ലാ കോഴ്സുകളും പൂർത്തിയാകുമ്പോൾ പ്രോഗ്രാം സർട്ടിഫിക്കറ്റ് നൽകുന്നു. സർട്ടിഫിക്കേഷൻ ഹാജരല്ല, മൂല്യനിർണയം ചെയ്ത കഴിവാണ് പ്രതിഫലിപ്പിക്കാൻ രൂപകൽപ്പന ചെയ്തിരിക്കുന്നത്.</p><h2>ഹോട്ടൽ പരിശീലന സർട്ടിഫിക്കറ്റ് എന്ത് രേഖപ്പെടുത്തുന്നു?</h2><p>ഓരോ സർട്ടിഫിക്കറ്റും ഒരു തൊഴിലുടമയ്ക്ക് ആവശ്യമായ വസ്തുതകൾ മാത്രം രേഖപ്പെടുത്തുന്നു.</p><ul><li>പഠിതാവിന്റെ പേര്</li><li>പൂർത്തിയാക്കിയ കോഴ്സ് അല്ലെങ്കിൽ പ്രോഗ്രാം</li><li>പൂർത്തീകരണ തീയതിയും അന്തിമ സ്കോറും</li><li>ഒരു അദ്വിതീയ സർട്ടിഫിക്കറ്റ് നമ്പർ, സ്ഥിരീകരണ കോഡ്, QR കോഡ്</li><li>സുരക്ഷ, ഭക്ഷ്യസുരക്ഷ പോലെ കാലാനുസൃതമായ പുതുക്കൽ ആവശ്യമുള്ള വിഷയങ്ങൾക്ക് കാലാവധി തീയതി</li></ul><h2>ഹോട്ടൽ പരിശീലന സർട്ടിഫിക്കറ്റ് എങ്ങനെ സ്ഥിരീകരിക്കാം?</h2><p>പൊതു സ്ഥിരീകരണ പേജ് ഉപയോഗിക്കുക. അക്കൗണ്ട് ആവശ്യമില്ല.</p><ol><li><a href="/en/verify">സർട്ടിഫിക്കറ്റ് സ്ഥിരീകരണ പേജ്</a> തുറക്കുക.</li><li>സർട്ടിഫിക്കറ്റിൽ അച്ചടിച്ചിരിക്കുന്ന സ്ഥിരീകരണ കോഡ് നൽകുക, അല്ലെങ്കിൽ അതിന്റെ QR കോഡ് സ്കാൻ ചെയ്യുക.</li><li>ലഭിക്കുന്ന നില വായിക്കുക: സാധുവായത്, കാലാവധി കഴിഞ്ഞത്, റദ്ദാക്കിയത് അല്ലെങ്കിൽ കണ്ടെത്തിയില്ല.</li></ol><p>സാധുവായ ഫലം പഠിതാവിന്റെ പേര്, വിഷയം, നൽകിയ തീയതി എന്നിവ കാണിക്കുന്നു, വ്യക്തിയെക്കുറിച്ച് മറ്റൊന്നും കാണിക്കുന്നില്ല.</p><h2>ഒരു സർട്ടിഫിക്കറ്റ് റദ്ദാക്കിയതായി കാണിച്ചേക്കാവുന്നത് എന്തുകൊണ്ട്?</h2><p>പിഴവായി നൽകിയതാണെങ്കിൽ, അതിന് പിന്നിലെ മൂല്യനിർണയ ഫലം അസാധുവാണെന്ന് കണ്ടെത്തിയാൽ, അല്ലെങ്കിൽ നൽകിയ സ്ഥാപനത്തിന്റെ അഭ്യർത്ഥന പ്രകാരം ഒരു സർട്ടിഫിക്കറ്റ് റദ്ദാക്കപ്പെടുന്നു. റദ്ദാക്കിയ സർട്ടിഫിക്കറ്റ് അപ്രത്യക്ഷമാകുന്നതിന് പകരം സ്ഥിരീകരിക്കാവുന്നതായി തുടരുകയും റദ്ദാക്കിയ നില നൽകിക്കൊണ്ടിരിക്കുകയും ചെയ്യുന്നു, അതിനാൽ മുമ്പത്തെ ഒരു പകർപ്പ് നിലവിലുള്ളതായി അവതരിപ്പിക്കാനാവില്ല.</p><h2>സർട്ടിഫിക്കറ്റുകൾ നൽകുന്നത് ആരാണ്?</h2><p>സൗദി അറേബ്യയിലെ റിയാദിൽ Altus Advisory പ്രവർത്തിപ്പിക്കുന്ന altus Hospitality Knowledge &amp; Performance പ്ലാറ്റ്ഫോമിലൂടെയാണ് സർട്ടിഫിക്കറ്റുകൾ നൽകുന്നത്. ഒരു സർട്ടിഫിക്കറ്റ് ഒരു പ്രത്യേക വ്യക്തി ഒരു പ്രത്യേക തീയതിയിൽ ഒരു പ്രത്യേക കോഴ്സ് അല്ലെങ്കിൽ പ്രോഗ്രാം പൂർത്തിയാക്കിയത് രേഖപ്പെടുത്തുന്നു. ഇത് ഒരു ലൈസൻസോ നിയന്ത്രണ അംഗീകാരമോ ഉടമ ഏതെങ്കിലും പ്രത്യേക റോളിന് യോഗ്യനാണെന്ന പ്രസ്താവനയോ അല്ല.</p><p>ലഭ്യമായ <a href="/en/programs">സർട്ടിഫിക്കേഷൻ പ്രോഗ്രാമുകൾ</a> ബ്രൗസ് ചെയ്യുക, അല്ലെങ്കിൽ നിങ്ങളുടെ ഹോട്ടൽ ജീവനക്കാരെ സർട്ടിഫൈ ചെയ്യുന്നതിനെക്കുറിച്ച് <a href="/en/contact">അക്കാദമി ടീമിനോട് ചോദിക്കുക</a>.</p>',
      'cta_label' => 'ഒരു സർട്ടിഫിക്കറ്റ് സ്ഥിരീകരിക്കുക',
      'meta_title' => 'ഹോട്ടൽ പരിശീലന സർട്ടിഫിക്കറ്റ് സ്ഥിരീകരിക്കുക | Hospitality Academy',
      'meta_description' => 'Hospitality Academy ഹോട്ടൽ പരിശീലന സർട്ടിഫിക്കറ്റ് കോഡ് അല്ലെങ്കിൽ QR വഴി സ്ഥിരീകരിക്കുക; അത് എന്ത് രേഖപ്പെടുത്തുന്നു, കാലാവധി, റദ്ദാക്കൽ കാരണങ്ങൾ എന്നിവ അറിയുക.',
      'focus_keyword' => 'ഹോട്ടൽ പരിശീലന സർട്ടിഫിക്കറ്റ് സ്ഥിരീകരണം',
    ),
    'contact' => 
    array (
      'title' => 'Hospitality Academy-യുമായി ബന്ധപ്പെടുക',
      'subtitle' => 'നിങ്ങളുടെ പ്രോപ്പർട്ടികളെയും ടീമിനെയും കുറിച്ച് ഞങ്ങളോട് പറയൂ, ഒരു ബ്രോഷറല്ല, ഒരു ഘടനയുമായി ഞങ്ങൾ തിരികെ വരും.',
      'body' => '<h2>എന്റെ പ്രോപ്പർട്ടിക്കായി ഹോട്ടൽ പരിശീലനം എങ്ങനെ അഭ്യർത്ഥിക്കാം?</h2><p>റിയാദിലോ രാജ്യത്തെ മറ്റെവിടെയെങ്കിലുമോ ഉള്ള ഹോട്ടൽ പരിശീലനത്തെക്കുറിച്ചുള്ള നിങ്ങളുടെ അന്വേഷണം ഈ പേജിലെ ഫോം വഴി അയയ്ക്കുക. സൗദി അറേബ്യ രാജ്യത്തെ റിയാദിലുള്ള Altus Advisory-യിലെ Hospitality Academy ടീമിലെ ഒരംഗം ഒരു കോൾ ക്രമീകരിക്കാൻ മറുപടി നൽകും. ഓട്ടോമേറ്റഡ് ഇമെയിൽ പരമ്പരയില്ല, നിങ്ങളുടെ വിവരങ്ങൾ ഒരു മൂന്നാം കക്ഷിക്കും കൈമാറുന്നില്ല.</p><h2>എന്റെ അന്വേഷണത്തിൽ എന്തൊക്കെ ഉൾപ്പെടുത്തണം?</h2><p>ഏതാനും വസ്തുതകൾ ഒരു പൊതു അവതരണത്തിന് പകരം പ്രവർത്തനക്ഷമമായ ഒരു ഘടനയുമായി മറുപടി നൽകാൻ ഞങ്ങളെ സഹായിക്കുന്നു.</p><ul><li>ഉൾപ്പെടുന്ന പ്രോപ്പർട്ടികളും നഗരങ്ങളും</li><li>നിങ്ങൾ ആരംഭിക്കാൻ ആഗ്രഹിക്കുന്ന വകുപ്പുകൾ</li><li>ഓരോ വകുപ്പിലെയും ഏകദേശ ജീവനക്കാരുടെ എണ്ണം</li><li>നിങ്ങളുടെ ജീവനക്കാർക്ക് ആവശ്യമായ ഭാഷകൾ: അറബി, ഇംഗ്ലീഷ്, അല്ലെങ്കിൽ ഹിന്ദി, ഉറുദു, ഫിലിപ്പിനോ, ബംഗാളി, നേപ്പാളി, മലയാളം പോലുള്ള തൊഴിൽസേനാ ഭാഷകൾ</li><li>പ്രീ-ഓപ്പണിംഗ് അല്ലെങ്കിൽ ഒരു പരിശോധന പോലെയുള്ള ഏതെങ്കിലും സമയപരിധി</li></ul><h2>ഞാൻ ബന്ധപ്പെട്ട ശേഷം എന്ത് സംഭവിക്കും?</h2><p>പ്രക്രിയ ചെറുതാണ്, ഓട്ടോമേഷനല്ല, ആളുകളാണ് കൈകാര്യം ചെയ്യുന്നത്.</p><ol><li>ഒരു ആമുഖ കോൾ ക്രമീകരിക്കാൻ ഞങ്ങൾ മറുപടി നൽകുന്നു.</li><li>നിങ്ങളുടെ പ്രോപ്പർട്ടികൾ, ജോലി റോളുകൾ, നിലവിലെ മാനദണ്ഡങ്ങൾ എന്നിവ ഞങ്ങൾ ചർച്ച ചെയ്യുന്നു.</li><li>നിങ്ങളുടെ ടീമിനായി വകുപ്പുകൾ, റോളുകൾ, നിർബന്ധിത പരിശീലനം എന്നിവയുടെ ഒരു ഘടന ഞങ്ങൾ നിർദ്ദേശിക്കുന്നു.</li></ol><h2>പരിശീലനമല്ലാത്ത മറ്റെന്തെങ്കിലും കാര്യത്തിന് Altus Advisory-യെ ബന്ധപ്പെടാമോ?</h2><p>ഉവ്വ്. സൗദി അറേബ്യയിലെയും GCC-യിലെയും ഹോട്ടൽ ഉടമകൾക്കും നിക്ഷേപകർക്കും ഹോട്ടൽ വികസനം, ഓണർ റെപ്രസന്റേഷൻ, പ്രീ-ഓപ്പണിംഗ് പിന്തുണ, പ്രവർത്തനങ്ങൾ, ഗസ്റ്റ് എക്സ്പീരിയൻസ്, വാണിജ്യ പ്രകടനം, വിശാലമായ ബിസിനസ് വളർച്ച എന്നിവയിൽ Altus Advisory ഉപദേശം നൽകുന്നു. <a href="/en/altus">Altus Advisory-യെയും അതിന്റെ സേവനങ്ങളെയും</a> കുറിച്ച് വായിക്കുക.</p><h2>സർട്ടിഫിക്കറ്റ് സംബന്ധമായ ചോദ്യവുമായി ഞാൻ എവിടെ പോകണം?</h2><p>ഒരു സർട്ടിഫിക്കറ്റ് യഥാർത്ഥമാണോ എന്ന് ഉറപ്പാക്കാൻ, <a href="/en/verify">സർട്ടിഫിക്കറ്റ് സ്ഥിരീകരണ പേജ്</a> നേരിട്ട് ഉപയോഗിക്കുക; അന്വേഷണം ആവശ്യമില്ല. നിങ്ങളുടെ സ്വന്തം പഠന രേഖയുടെ പകർപ്പോ അതിലെ തിരുത്തലോ അഭ്യർത്ഥിക്കാൻ, നിങ്ങളുടെ തൊഴിലുടമയുടെ അഡ്മിനിസ്ട്രേറ്ററെ ബന്ധപ്പെടുക അല്ലെങ്കിൽ ഈ പേജ് വഴി ഞങ്ങൾക്ക് എഴുതുക.</p><p>എഴുതുന്നതിന് മുമ്പ്, <a href="/en/hotels">ഹോട്ടലുകൾക്കായി പ്ലാറ്റ്ഫോം എങ്ങനെ പ്രവർത്തിക്കുന്നു</a> എന്ന് കാണുന്നതോ <a href="/en/courses">കോഴ്സ് കാറ്റലോഗ്</a> ബ്രൗസ് ചെയ്യുന്നതോ ഉപകാരപ്രദമായേക്കാം.</p>',
      'cta_label' => 'നിങ്ങളുടെ അന്വേഷണം അയയ്ക്കുക',
      'meta_title' => 'ബന്ധപ്പെടുക: റിയാദിലെ ഹോട്ടൽ പരിശീലനം | Altus Advisory',
      'meta_description' => 'റിയാദിലെയും സൗദി അറേബ്യയിലുടനീളവുമുള്ള ഹോട്ടൽ പരിശീലനത്തിനായി Altus Advisory-യിലെ Hospitality Academy-യെ ബന്ധപ്പെടുക. പ്രോപ്പർട്ടികളും വകുപ്പുകളും സമയപരിധികളും അറിയിക്കുക.',
      'focus_keyword' => 'റിയാദിലെ ഹോട്ടൽ പരിശീലനം',
    ),
    'privacy' => 
    array (
      'title' => 'സ്വകാര്യതാ നയം',
      'subtitle' => 'അക്കാദമി എന്ത് സൂക്ഷിക്കുന്നു, എന്തിന് സൂക്ഷിക്കുന്നു, ആർക്ക് കാണാനാകും, എത്ര കാലം സൂക്ഷിക്കുന്നു.',
      'body' => '<h2>ഈ നയം ആരെയൊക്കെ ഉൾക്കൊള്ളുന്നു</h2><p>സൗദി അറേബ്യ രാജ്യത്തെ റിയാദിൽ Altus Advisory പ്രവർത്തിപ്പിക്കുന്ന പരിശീലന അക്കാദമിയായ Hospitality Academy-ക്കും, തൊഴിലുടമ വഴിയോ നേരിട്ടോ അത് ഉപയോഗിക്കുന്ന പഠിതാക്കൾക്കും ഈ നയം ബാധകമാണ്.</p><h2>ശേഖരിക്കുന്നവ</h2><p>ഒരു പഠിതാവിനായി അക്കാദമി സൂക്ഷിക്കുന്നത്:</p><ul><li>പേര്, ജോലി ഇമെയിൽ, നൽകിയിട്ടുണ്ടെങ്കിൽ മൊബൈൽ നമ്പർ</li><li>തൊഴിലുടമ, പ്രോപ്പർട്ടി, വകുപ്പ്, ജോലി റോൾ</li><li>പഠന രേഖ: എൻറോൾമെന്റുകൾ, പാഠ പുരോഗതി, മൂല്യനിർണയ ശ്രമങ്ങളും സ്കോറുകളും, സർട്ടിഫിക്കറ്റുകൾ, നടപടിക്രമ അംഗീകാരങ്ങൾ</li></ul><h2>എന്തിനാണ് ശേഖരിക്കുന്നത്</h2><p>വിവരങ്ങൾ ഉപയോഗിക്കുന്നത്:</p><ul><li>പരിശീലനം നൽകാൻ</li><li>പരിശീലനം പൂർത്തിയാക്കിയോ എന്ന് രേഖപ്പെടുത്താൻ</li><li>സർട്ടിഫിക്കറ്റുകൾ നൽകാനും സ്ഥിരീകരിക്കാനും</li><li>ഒരു തൊഴിലുടമയ്ക്ക് സ്വന്തം ജീവനക്കാരുടെ അനുസരണ നില കാണാൻ അനുവദിക്കാൻ</li></ul><p>ഒന്നും വിൽക്കുന്നില്ല, ഒന്നും പരസ്യത്തിനായി ഉപയോഗിക്കുന്നില്ല.</p><h2>നടപടിക്രമ അംഗീകാരങ്ങൾ</h2><p>ഒരു അംഗീകാരം ഉപയോക്താവ്, കൃത്യമായ നടപടിക്രമ പതിപ്പ്, ടൈംസ്റ്റാമ്പ്, ഉത്ഭവിച്ച നെറ്റ്‌വർക്ക് വിലാസം എന്നിവ രേഖപ്പെടുത്തുന്നു. ഇത് ബോധപൂർവമാണ്: ഒരു വ്യക്തി, ഒരു പതിപ്പ്, ഒരു നിമിഷം എന്നിവയുമായി ബന്ധിപ്പിക്കാനാകാത്ത അംഗീകാരം ഒന്നിനും തെളിവല്ല.</p><h2>പഠന രേഖ ആർക്കൊക്കെ കാണാം</h2><p>ഒരു പഠന രേഖ കാണാനാകുന്നവർ:</p><ul><li>പഠിതാവ്</li><li>പഠിതാവിന്റെ ലൈൻ മാനേജർ</li><li>അതേ സ്ഥാപനത്തിനുള്ളിലെ വകുപ്പ്, പ്രോപ്പർട്ടി, സ്ഥാപന അഡ്മിനിസ്ട്രേറ്റർമാർ</li><li>ഒരു അക്കാദമി അഡ്മിനിസ്ട്രേറ്റർ</li></ul><p>ഒരു സ്ഥാപനത്തിനും മറ്റൊരു സ്ഥാപനത്തിന്റെ ഡാറ്റ കാണാനാവില്ല.</p><h2>സൂക്ഷിക്കൽ കാലയളവ്</h2><p>അക്കൗണ്ട് സജീവമായിരിക്കുന്നിടത്തോളം പഠന രേഖകളും സർട്ടിഫിക്കറ്റുകളും സൂക്ഷിക്കുന്നു, അതിനുശേഷം നൽകിയ സ്ഥാപനത്തിന് ഓഡിറ്റിനായി ആവശ്യമുള്ളിടത്തോളം കാലം. സ്ഥിരീകരണം പ്രവർത്തിച്ചുകൊണ്ടിരിക്കാൻ സർട്ടിഫിക്കറ്റ് രേഖ അനിശ്ചിതകാലം സൂക്ഷിക്കുന്നു.</p><h2>നിങ്ങളുടെ അഭ്യർത്ഥനകൾ</h2><p>ഒരു പഠിതാവിന് തന്റെ രേഖയുടെ പകർപ്പോ അതിലെ തിരുത്തലോ തൊഴിലുടമയുടെ അഡ്മിനിസ്ട്രേറ്റർ വഴിയോ <a href="/en/contact">ബന്ധപ്പെടാനുള്ള പേജ്</a> വഴി അക്കാദമിയെ നേരിട്ട് ബന്ധപ്പെട്ടോ അഭ്യർത്ഥിക്കാം. അക്കൗണ്ടുകൾക്കും സർട്ടിഫിക്കറ്റുകൾക്കുമുള്ള നിയമങ്ങൾ <a href="/en/terms">ഉപയോഗ നിബന്ധനകളിൽ</a> വ്യക്തമാക്കിയിരിക്കുന്നു.</p>',
      'cta_label' => 'അക്കാദമിയെ ബന്ധപ്പെടുക',
      'meta_title' => 'സ്വകാര്യതാ നയം | Hospitality Academy by Altus Advisory',
      'meta_description' => 'Hospitality Academy സ്വകാര്യതാ നയം: ഏത് പഠിതാവ് ഡാറ്റ ശേഖരിക്കുന്നു, എന്തിന്, പഠന രേഖ ആർക്ക് കാണാം, രേഖകളും സർട്ടിഫിക്കറ്റുകളും എത്ര കാലം സൂക്ഷിക്കുന്നു.',
