    'terms' => 
    array (
      'title' => 'ഉപയോഗ നിബന്ധനകൾ',
      'subtitle' => 'അക്കാദമി ഉപയോഗിക്കുന്നതിനും അത് നൽകുന്ന സർട്ടിഫിക്കറ്റുകൾക്കും ബാധകമായ നിബന്ധനകൾ.',
      'body' => '<h2>വ്യാപ്തി</h2><p>സൗദി അറേബ്യ രാജ്യത്തെ റിയാദിൽ Altus Advisory പ്രവർത്തിപ്പിക്കുന്ന Hospitality Academy-ക്കും അതിലൂടെ നൽകുന്ന സർട്ടിഫിക്കറ്റുകൾക്കും ഈ നിബന്ധനകൾ ബാധകമാണ്.</p><h2>അക്കൗണ്ടുകൾ</h2><p>ഒരു അക്കൗണ്ട് പേരുള്ള ഒരു വ്യക്തിയുടേതാണ്.</p><ul><li>അക്കൗണ്ട് പങ്കിടുന്നത് അനുവദനീയമല്ല.</li><li>മറ്റൊരാൾക്ക് വേണ്ടി പരിശീലനം പൂർത്തിയാക്കുന്നത് അനുവദനീയമല്ല.</li></ul><p>ഇതിൽ ഏത് രീതിയും അതിൽ നിന്നുണ്ടാകുന്ന ഏത് സർട്ടിഫിക്കറ്റിനെയും അസാധുവാക്കുകയും അക്കൗണ്ട് സസ്പെൻഡ് ചെയ്യാനുള്ള കാരണമാകുകയും ചെയ്യുന്നു.</p><h2>മൂല്യനിർണയങ്ങൾ</h2><p>മൂല്യനിർണയ ശ്രമങ്ങൾ ടൈംസ്റ്റാമ്പും ശ്രമ നമ്പറും സഹിതം രേഖപ്പെടുത്തുന്നു. ശ്രമ പരിധികൾ, സമയ പരിധികൾ, ചോദ്യ ക്രമരഹിതമാക്കൽ എന്നിവ ഓരോ മൂല്യനിർണയത്തിനും ക്രമീകരിച്ചതുപോലെ പ്രയോഗിക്കുന്നു. ആ നിയന്ത്രണങ്ങൾ മറികടന്ന് നേടുന്ന ഫലം അസാധുവാണ്.</p><h2>സർട്ടിഫിക്കറ്റുകൾ</h2><p>ഒരു സർട്ടിഫിക്കറ്റ് ഒരു പ്രത്യേക വ്യക്തി ഒരു പ്രത്യേക തീയതിയിൽ ഒരു പ്രത്യേക കോഴ്സ് അല്ലെങ്കിൽ പ്രോഗ്രാം പൂർത്തിയാക്കിയത് രേഖപ്പെടുത്തുന്നു. ഇത് ഒരു ലൈസൻസോ നിയന്ത്രണ അംഗീകാരമോ ഉടമ ഏതെങ്കിലും പ്രത്യേക റോളിന് യോഗ്യനാണെന്ന പ്രസ്താവനയോ അല്ല. അത്തരം ഏത് ഉപയോഗവും ഈ നിബന്ധനകൾക്ക് പുറത്താണ്. സർട്ടിഫിക്കറ്റ് നില <a href="/en/verify">സ്ഥിരീകരണ പേജിൽ</a> പരിശോധിക്കാം.</p><h2>ഉള്ളടക്കം</h2><p>അക്കാദമി പ്രസിദ്ധീകരിക്കുന്ന കോഴ്സ് സാമഗ്രികളും നടപടിക്രമങ്ങളും അക്കാദമിയുടെയോ അവ രചിച്ച സ്ഥാപനത്തിന്റെയോ സ്വത്തായി തുടരുന്നു. ഒരു സ്ഥാപനം അപ്‌ലോഡ് ചെയ്യുന്ന നടപടിക്രമങ്ങൾ ആ സ്ഥാപനത്തിന്റെ സ്വത്തായി തുടരുന്നു, മറ്റൊരു സ്ഥാപനവുമായും പങ്കിടുന്നില്ല.</p><h2>ലഭ്യത</h2><p>സേവനം തുടർച്ചയായി ലഭ്യമാക്കാൻ അക്കാദമി ലക്ഷ്യമിടുന്നു, പക്ഷേ തടസ്സമില്ലാത്ത പ്രവേശനം ഉറപ്പ് നൽകുന്നില്ല. പ്രവേശനം തടസ്സപ്പെടുമെന്ന് പ്രതീക്ഷിക്കുന്നിടത്ത് ആസൂത്രിത മെയിന്റനൻസ് മുൻകൂട്ടി അറിയിക്കുന്നു.</p><h2>ബന്ധപ്പെട്ട നയങ്ങൾ</h2><p>വ്യക്തിഗത ഡാറ്റ എങ്ങനെ കൈകാര്യം ചെയ്യുന്നുവെന്ന് <a href="/en/privacy">സ്വകാര്യതാ നയത്തിൽ</a> വിവരിച്ചിരിക്കുന്നു.</p>',
      'cta_label' => 'സ്വകാര്യതാ നയം വായിക്കുക',
      'meta_title' => 'ഉപയോഗ നിബന്ധനകൾ | Hospitality Academy by Altus Advisory',
      'meta_description' => 'Hospitality Academy ഉപയോഗ നിബന്ധനകൾ: അക്കൗണ്ടുകൾക്കും മൂല്യനിർണയങ്ങൾക്കുമുള്ള നിയമങ്ങൾ, സർട്ടിഫിക്കറ്റ് എന്ത് പ്രസ്താവിക്കുന്നു, ഉള്ളടക്ക ഉടമസ്ഥത, ലഭ്യത.',
