  'topic' => 
  array (
    'front-office-training' => 
    array (
      'title' => 'ഫ്രണ്ട് ഓഫീസ് പരിശീലനം',
      'intro' => '<p>ഒരു അതിഥി ഡെസ്കിൽ എത്തുന്നത് മുതൽ അവരുടെ ഫോളിയോ അടയ്ക്കുന്നത് വരെ നടക്കുന്നതെല്ലാം ഫ്രണ്ട് ഓഫീസ് പരിശീലനം ഉൾക്കൊള്ളുന്നു. സേവന പരാജയം ഏറ്റവും ദൃശ്യമാകുന്നതും നടപടിക്രമ പിഴവ് ഏറ്റവും ചെലവേറിയതുമായ വകുപ്പാണിത്, കാരണം തെറ്റായ റൂം അസൈൻമെന്റ്, സ്ഥിരീകരിക്കാത്ത തിരിച്ചറിയൽ, തെറ്റായി പോസ്റ്റ് ചെയ്ത ചാർജ് എന്നിവയെല്ലാം പിന്നീട് പരാതിയായോ ഓഡിറ്റ് കണ്ടെത്തലായോ പുറത്തുവരും.</p><h2>ഫ്രണ്ട് ഓഫീസ് പരിശീലനം ഉൾക്കൊള്ളേണ്ടത്</h2><p>വരവിന്റെയും പുറപ്പെടലിന്റെയും ക്രമങ്ങൾ ക്രമത്തിൽ, അതിഥി രജിസ്ട്രേഷനും അത് സൃഷ്ടിക്കുന്ന രേഖകളും, ഹോട്ടൽ നിറഞ്ഞിരിക്കുമ്പോഴുള്ള റൂം അസൈൻമെന്റ്, സഹജബോധത്തിന് പകരം ഒരു രീതിയോടെയുള്ള പരാതി കൈകാര്യം ചെയ്യൽ, ടെലിഫോൺ മാനദണ്ഡങ്ങൾ, അതിഥിയെ സമ്മർദ്ദത്തിലാക്കാത്ത അപ്‌സെല്ലിംഗ്, ഹോട്ടൽ ദിവസം അവസാനിപ്പിക്കുന്ന നൈറ്റ് ഓഡിറ്റ്.</p><h2>ഫലപ്രദമായ ക്രമം</h2><p>മേൽനോട്ടമില്ലാത്ത ഷിഫ്റ്റിൽ ജോലി ചെയ്യുന്നതിന് മുമ്പ് പുതിയ ഏജന്റ് ആദ്യം അടിസ്ഥാനങ്ങളും ടെലിഫോൺ മര്യാദകളും, തുടർന്ന് ചെക്ക്-ഇൻ, ചെക്ക്-ഔട്ട്, രജിസ്ട്രേഷൻ, പിന്നെ പ്രോപ്പർട്ടി മാനേജ്മെന്റ് സിസ്റ്റം എന്നിവ പൂർത്തിയാക്കണം. അടിസ്ഥാന ക്രമം സ്വാഭാവികമായിക്കഴിഞ്ഞാൽ പരാതി കൈകാര്യം ചെയ്യലും നൈറ്റ് ഓഡിറ്റും പിന്നീട് വരുന്നു.</p><h2>പുരോഗതി അളക്കുന്ന വിധം</h2><p>ഓരോ കോഴ്സും ഒരു മൂല്യനിർണയത്തോടെ അവസാനിക്കുന്നു, പ്രവർത്തനപരമായ കോഴ്സുകൾക്കൊപ്പം പഠിതാവ് സ്വന്തം വകുപ്പിൽ പ്രവർത്തിപ്പിക്കുന്ന ഒരു ചെക്ക്‌ലിസ്റ്റും ഉണ്ട്. പൂർത്തീകരണം ഷിഫ്റ്റിനല്ല, വ്യക്തിക്കാണ് രേഖപ്പെടുത്തുന്നത്, അതിനാൽ ആരാണ് ഒറ്റയ്ക്ക് ജോലി ചെയ്യാൻ തയ്യാറെന്ന് മാനേജർക്ക് കാണാനാകും.</p>',
    ),
    'housekeeping-training' => 
    array (
      'title' => 'ഹൗസ്‌കീപ്പിംഗ് പരിശീലനം',
      'intro' => '<p>ഒരു മുറിയെ പ്രവചനാതീതമല്ലാത്തതാക്കാനാണ് ഹൗസ്‌കീപ്പിംഗ് പരിശീലനം. ഒരേ മുറി വൃത്തിയാക്കുന്ന രണ്ട് അറ്റൻഡന്റുമാർ ഒരേ ഫലം നൽകണം, ഒരു ഇൻസ്പെക്ടർക്ക് ഇരുവരെയും ഒരേ രേഖാമൂലമുള്ള മാനദണ്ഡമനുസരിച്ച് സ്കോർ ചെയ്യാനാകണം.</p><h2>പരിശ്രമത്തേക്കാൾ ക്രമം പ്രധാനമാകുന്നത് എന്തുകൊണ്ട്</h2><p>മിക്ക ഹൗസ്‌കീപ്പിംഗ് പരാജയങ്ങളും പരിശ്രമത്തിന്റേതല്ല, ക്രമത്തിന്റെ പരാജയങ്ങളാണ്. രാസവസ്തു പ്രയോഗിക്കുന്നതിന് മുമ്പ് ബാത്ത്റൂം വൃത്തിയാക്കൽ, വാതിലിന് നേരെ വാക്വം ചെയ്യുന്നതിന് പകരം ദൂരെയുള്ള മൂലയിലേക്ക് വാക്വം ചെയ്യൽ, പൊടി തുടയ്ക്കുന്നതിന് മുമ്പ് കിടക്ക വിരിക്കൽ എന്നിവയെല്ലാം കൂടുതൽ സമയമെടുത്തതും മോശമായി കാണുന്നതുമായ ഒരു മുറി നൽകുന്നു. ക്രമം പരിശീലിപ്പിക്കുന്നതാണ് ഓരോ മുറിക്കുമുള്ള സമയം പ്രവചിക്കാവുന്നതാക്കുന്നത്.</p><h2>സുരക്ഷ മാനദണ്ഡത്തിന്റെ ഭാഗമാണ്</h2><p>രാസവസ്തു സുരക്ഷ ഒരു അധിക മൊഡ്യൂളല്ല. നേർപ്പിക്കൽ, പ്രവർത്തന സമയം, കയ്യുറ ഉപയോഗം, ഉൽപ്പന്നങ്ങൾ ഒരിക്കലും കലർത്താതിരിക്കൽ, ബാത്ത്റൂം തുണി ഗ്ലാസിലെത്തുന്നത് തടയുന്ന നിറക്കോഡുള്ള തുണി അച്ചടക്കം എന്നിവയെല്ലാം ശരിയായി വൃത്തിയാക്കലിന്റെ ഭാഗമാണ്, അതിനാൽ അവ വൃത്തിയാക്കലിനൊപ്പം തന്നെ പഠിപ്പിക്കുന്നു.</p><h2>പരിശോധന ചക്രം പൂർത്തിയാക്കുന്നു</h2><p>പരിശീലനം ലഭിച്ച മാനദണ്ഡമനുസരിച്ച് പരിശോധിക്കപ്പെടുന്ന അറ്റൻഡന്റിന് വ്യക്തമായ ഫീഡ്ബാക്ക് നൽകാനാകും. ഇവിടെ പരിശീലനവും പരിശോധനയും ഒരേ ചെക്ക്‌ലിസ്റ്റാണ് ഉപയോഗിക്കുന്നത്, അതാണ് പരാജയപ്പെട്ട പരിശോധനയെ തർക്കമല്ല, ഒരു കോച്ചിംഗ് സംഭാഷണമാക്കുന്നത്.</p>',
    ),
    'food-safety-training' => 
    array (
      'title' => 'ഹോട്ടലുകൾക്കുള്ള ഭക്ഷ്യസുരക്ഷാ പരിശീലനം',
      'intro' => '<p>ഒരു ഹോട്ടലിനോട് തെളിവ് ആവശ്യപ്പെടാൻ ഏറ്റവും സാധ്യതയുള്ള പരിശീലനവും, വിടവിന് അതിഥി പരാതിക്കപ്പുറമുള്ള പ്രത്യാഘാതങ്ങളുള്ള പരിശീലനവുമാണ് ഭക്ഷ്യസുരക്ഷാ പരിശീലനം.</p><h2>പ്രധാനപ്പെട്ട നിയന്ത്രണ ബിന്ദുക്കൾ</h2><p>സ്വീകരണ താപനില, സംഭരണ ക്രമവും തീയതികളും, പാചക താപനില, ഹോട്ട് ഹോൾഡിംഗ്, തണുപ്പിക്കൽ സമയം, ഒരിക്കൽ മാത്രം വീണ്ടും ചൂടാക്കൽ, അലർജൻ വേർതിരിക്കൽ. ഓരോന്നും ഒരു പരാജയം കണ്ടെത്താനും തിരുത്താനും കഴിയുന്ന ബിന്ദുവാണ്, ഓരോന്നും ഒരു രേഖ സൃഷ്ടിക്കുന്നു.</p><h2>രേഖയാണ് പരിശീലനത്തിന്റെ ഫലം</h2><p>പരിശീലനം ലഭിച്ച ടീം ശൂന്യമായ കള്ളികളില്ലാത്ത പൂർണമായ താപനില ലോഗും പരിധിക്ക് പുറത്തുള്ള ഓരോ റീഡിംഗിനും രേഖപ്പെടുത്തിയ തിരുത്തൽ നടപടിയും നൽകുന്നു. അപൂർണമായ ലോഗ് കടലാസുപണി പ്രശ്നമല്ല, പരിശീലന വിടവാണ്, അതിനാൽ അക്കാദമി ലോഗ് പൂർത്തിയാക്കലിനെ ഭരണപരമായ ജോലിയായല്ല, കഴിവിന്റെ ഭാഗമായാണ് കാണുന്നത്.</p><h2>ആർക്കാണ് ഇത് ആവശ്യം</h2><p>അടുക്കള ടീമുകൾക്ക് മുഴുവൻ പരിശീലനവും ആവശ്യമാണ്. സേവന ടീമുകൾക്ക് പാസിലെ താപനില അവബോധം, അലർജൻ ചോദ്യങ്ങൾ, വ്യക്തിശുചിത്വം എന്നിവ ആവശ്യമാണ്. സ്വീകരണ ക്ലാർക്കുമാർക്ക് ഡെലിവറി പരിശോധനകൾ ആവശ്യമാണ്. മിനിബാർ അല്ലെങ്കിൽ ഇൻ-റൂം വിതരണം ഉൾപ്പെടുന്നിടത്ത് ഹൗസ്‌കീപ്പിംഗിനും ഇത് ആവശ്യമാണ്.</p>',
    ),
    'hotel-sop-training' => 
    array (
      'title' => 'ഹോട്ടൽ SOP പരിശീലനം',
      'intro' => '<p>ആരും വായിച്ചിട്ടില്ലാത്ത ഒരു സ്റ്റാൻഡേർഡ് ഓപ്പറേറ്റിംഗ് പ്രൊസീജർ ഒരു രേഖ മാത്രമാണ്, നിയന്ത്രണമല്ല. SOP പരിശീലനമാണ് രേഖയെ നിയന്ത്രണമാക്കി മാറ്റുന്നത്.</p><h2>ഉപയോഗയോഗ്യമായ SOP-ൽ ഉള്ളത്</h2><p>ഒരു ഉദ്ദേശ്യം, വ്യാപ്തി, പേരുള്ള ഉത്തരവാദിത്തങ്ങൾ, ആവശ്യമായ ഉപകരണങ്ങൾ, നിർവഹിക്കുന്ന ക്രമത്തിൽ നമ്പറിട്ട ഘട്ടങ്ങളായുള്ള നടപടിക്രമം, പ്രവർത്തിപ്പിക്കാവുന്ന ചെക്ക്‌ലിസ്റ്റ്, സുരക്ഷാ കുറിപ്പുകൾ, അളക്കാവുന്ന ഗുണനിലവാര മാനദണ്ഡം, എസ്കലേഷൻ മാർഗം. എസ്കലേഷൻ മാർഗമില്ലാത്ത നടപടിക്രമമാണ് പുലർച്ചെ മൂന്ന് മണിക്ക് പരാജയപ്പെടുന്നത്.</p><h2>പതിപ്പുകളും അംഗീകാരവും</h2><p>ഒരു നടപടിക്രമം മാറുമ്പോൾ, മുൻ പതിപ്പ് സൂക്ഷിക്കുകയും പുതിയത് മാറ്റങ്ങളുടെ സംഗ്രഹം, രചയിതാവ്, അംഗീകാരം നൽകുന്നയാൾ എന്നിവയോടെ പ്രസിദ്ധീകരിക്കുകയും ചെയ്യുന്നു. നടപടിക്രമം ബാധകമായ എല്ലാവരോടും പുതിയ പതിപ്പ് അംഗീകരിക്കാൻ ആവശ്യപ്പെടുന്നു, അംഗീകാരം പതിപ്പ്, വ്യക്തി, സമയം എന്നിവ രേഖപ്പെടുത്തുന്നു.</p><h2>നടപടിക്രമത്തിൽ നിന്ന് ചെക്ക്‌ലിസ്റ്റിലേക്ക്</h2><p>അക്കാദമിയിലെ ഓരോ നടപടിക്രമവും അതിന്റെ ചെക്ക്‌ലിസ്റ്റ് പ്രവർത്തിപ്പിക്കാവുന്ന ഇനമായി ഉൾക്കൊള്ളുന്നു, അതിനാൽ ഒരു സൂപ്പർവൈസർക്ക് ഘട്ടങ്ങൾ ഓർത്തെടുക്കുന്നതിന് പകരം ഷിഫ്റ്റിൽ പരിശോധന നടത്തി ഒപ്പിടാനാകും.</p>',
    ),
    'hospitality-certification' => 
    array (
      'title' => 'ഹോസ്പിറ്റാലിറ്റി സർട്ടിഫിക്കേഷൻ',
      'intro' => '<p>സർട്ടിഫിക്കേഷൻ ഉപയോഗപ്രദമാകുന്നത് അത് വ്യക്തമായ ഒന്ന് രേഖപ്പെടുത്തുകയും അവിടെ ഇല്ലാതിരുന്ന ഒരാൾക്ക് പരിശോധിക്കാനാകുകയും ചെയ്യുമ്പോഴാണ്. അക്കാദമി സ്വയം പാലിക്കുന്ന മാനദണ്ഡം അതാണ്.</p><h2>ഇവിടത്തെ സർട്ടിഫിക്കറ്റിന്റെ അർത്ഥം</h2><p>പേരുള്ള ഒരു വ്യക്തി പേരുള്ള ഒരു കോഴ്സിലെ എല്ലാ നിർബന്ധിത പാഠങ്ങളും പൂർത്തിയാക്കി, അതിന്റെ മൂല്യനിർണയം വിജയ മാർക്കിലോ അതിന് മുകളിലോ നേടി, രേഖപ്പെടുത്തിയ ഒരു തീയതിയിൽ. ഇതിൽ കൂടുതലൊന്നും സൂചിപ്പിക്കുന്നില്ല, കൂടുതലൊന്നും അച്ചടിക്കുന്നുമില്ല.</p><h2>സ്ഥിരീകരണം</h2><p>ഓരോ സർട്ടിഫിക്കറ്റിനും ഒരു സർട്ടിഫിക്കറ്റ് നമ്പറും സ്ഥിരീകരണ കോഡും ഉണ്ട്. ഒരു ഭാവി തൊഴിലുടമയ്ക്കോ ഓഡിറ്റർക്കോ ഇൻസ്പെക്ടർക്കോ പൊതു സ്ഥിരീകരണ പേജിൽ കോഡ് നൽകി, അക്കൗണ്ട് ഇല്ലാതെ തന്നെ, ഉടൻ നില കാണാനാകും.</p><h2>കാലാവധിയും പുതുക്കലും</h2><p>അടിസ്ഥാന മാനദണ്ഡവും വ്യക്തിയുടെ ഓർമയും മാറുന്നതിനാൽ സുരക്ഷ, ഭക്ഷ്യസുരക്ഷാ സർട്ടിഫിക്കറ്റുകൾക്ക് കാലാവധി തീയതിയുണ്ട്. കാലാവധി കഴിഞ്ഞതിന് ശേഷമല്ല, മുമ്പ് തന്നെ അക്കാദമി പഠിതാവിനും മാനേജർക്കും മുന്നറിയിപ്പ് നൽകുന്നു.</p>',
    ),
    'hotel-compliance-training' => 
    array (
      'title' => 'ഹോട്ടൽ കംപ്ലയൻസ് പരിശീലനം',
      'intro' => '<p>ഓരോ ജീവനക്കാരനും വേണ്ടി, ആവശ്യപ്പെടുമ്പോൾ, തീയതിയും പേരും സഹിതം ഒരു ഹോട്ടലിന് തെളിവ് നൽകാനാകേണ്ട വിഷയങ്ങളുടെ കൂട്ടമാണ് കംപ്ലയൻസ് പരിശീലനം.</p><h2>നിർബന്ധിത വിഷയങ്ങൾ</h2><p>അഗ്നി സുരക്ഷയും ഒഴിപ്പിക്കലും, അടിയന്തര പ്രതികരണം, ക്ലീനിംഗ് ഉൽപ്പന്നങ്ങൾ കൈകാര്യം ചെയ്യുന്ന ഏവർക്കും രാസവസ്തു സുരക്ഷ, ഭക്ഷണം തൊടുന്ന ഏവർക്കും ഭക്ഷ്യസുരക്ഷ, അടുക്കളയിൽ കത്തി സുരക്ഷ, അതിഥി രേഖകളിലേക്ക് പ്രവേശനമുള്ള ഏവർക്കും അതിഥി ഡാറ്റ സ്വകാര്യത.</p><h2>ഹാജരല്ല, തെളിവ്</h2><p>ഹാജർ ഷീറ്റ് ആരാണ് മുറിയിലുണ്ടായിരുന്നതെന്ന് കാണിക്കുന്നു. മൂല്യനിർണയ ഫലത്തോടുകൂടിയ പൂർത്തീകരണ രേഖ ആരാണ് അത് മനസ്സിലാക്കിയതെന്ന് കാണിക്കുന്നു. അക്കാദമി ഇവ രണ്ടും രേഖപ്പെടുത്തുന്നു, രണ്ടാമത്തേതിനെക്കുറിച്ച് റിപ്പോർട്ട് ചെയ്യുന്നു.</p><h2>കാലികമായി നിലനിർത്തൽ</h2><p>കംപ്ലയൻസ് വിഷയങ്ങൾക്ക് കാലാവധി നിശ്ചയിച്ചിരിക്കുന്നു, കാലാവധി മുന്നറിയിപ്പ് പഠിതാവിനും മാനേജർക്കും ഒരുമിച്ച് ലഭിക്കുന്നു. ബാക്കിയുള്ളതും കാലാവധി കഴിഞ്ഞതുമായ ഇനങ്ങൾ വകുപ്പ്, പ്രോപ്പർട്ടി എന്നിങ്ങനെ കാണാനാകും, അതിനാൽ ഒരു പരിശോധന കണ്ടെത്തുന്നതിന് മുമ്പ് വിടവ് കണ്ടെത്തപ്പെടുന്നു.</p>',
    ),
    'hotel-training-riyadh' => 
    array (
      'title' => 'റിയാദിലെ ഹോട്ടൽ ജീവനക്കാർക്കുള്ള പരിശീലനം',
      'intro' => '<p>റിയാദിലെ ഹോട്ടലുകൾ പ്രധാനമായും കോർപ്പറേറ്റ്, സർക്കാർ രീതിയിലാണ് പ്രവർത്തിക്കുന്നത്: പ്രവൃത്തിദിവസങ്ങളിൽ കൂടുതലുള്ള ഒക്യുപൻസി, ഒറ്റയ്ക്ക് യാത്ര ചെയ്യുന്ന ബിസിനസ് യാത്രക്കാരുടെ ഉയർന്ന പങ്ക്, ചെറിയ താമസങ്ങൾ, വിനോദ സീസണുകളേക്കാൾ മീറ്റിംഗ് ഷെഡ്യൂളുകളുമായി ബന്ധപ്പെട്ട വരവിന്റെ തിരക്കുകൾ.</p><h2>അത് പരിശീലനത്തിൽ വരുത്തുന്ന മാറ്റം</h2><p>ഒരു റിസോർട്ട് സാഹചര്യത്തേക്കാൾ ഫ്രണ്ട് ഓഫീസ് വേഗത ഇവിടെ പ്രധാനമാണ്, കാരണം രാത്രി ഒമ്പത് മണിക്ക് എത്തുന്ന ബിസിനസ് അതിഥിക്ക് വേണ്ടത് മുറിയാണ്, പരിചയപ്പെടുത്തൽ ടൂറല്ല. ചെക്ക്-ഇൻ, ചെക്ക്-ഔട്ട് സമയ മാനദണ്ഡങ്ങൾ, എക്സ്പ്രസ് ഡിപ്പാർച്ചർ, കമ്പനി ബില്ലിംഗ് താമസങ്ങൾക്കുള്ള കൃത്യമായ ഫോളിയോ കൈകാര്യം എന്നിവയ്ക്ക് കൺസിയേർജ് യാത്രാപദ്ധതി തയ്യാറാക്കലിനേക്കാൾ പ്രാധാന്യമുണ്ട്.</p><h2>മീറ്റിംഗുകളും ഇവന്റുകളും</h2><p>റിയാദിലെ പ്രോപ്പർട്ടികൾക്ക് മീറ്റിംഗുകളുടെയും ഇവന്റുകളുടെയും ഭാരം കൂടുതലാണ്, അതിനാൽ ബാങ്ക്വറ്റ് പ്രവർത്തനങ്ങൾ, ഫംഗ്ഷൻ ഷീറ്റ് വായന, ഇവന്റുകൾ, അടുക്കള, എഞ്ചിനീയറിംഗ് എന്നിവ തമ്മിലുള്ള ഏകോപനം എന്നിവ വെവ്വേറെയല്ല, ഒരു കൂട്ടമായി പരിശീലിപ്പിക്കുന്നു.</p><h2>ടീമുകൾക്ക് സാധാരണയായി ഏറ്റവും കൂടുതൽ പിന്തുണ വേണ്ടിടം</h2><p>പ്രവൃത്തിദിവസത്തിലെ ഫുൾ ഹൗസ് കൈകാര്യം ചെയ്യൽ, സമ്മർദ്ദത്തിലുള്ള റൂം അസൈൻമെന്റ്, ഉറപ്പ് നൽകിയ മുറി തയ്യാറല്ലാത്തപ്പോഴുള്ള പരാതി കൈകാര്യം ചെയ്യൽ, ധാരാളം കമ്പനി അക്കൗണ്ടുകളുള്ള പ്രോപ്പർട്ടിയിലെ നൈറ്റ് ഓഡിറ്റ്.</p>',
    ),
    'hotel-training-jeddah' => 
    array (
      'title' => 'ജിദ്ദയിലെ ഹോട്ടൽ ജീവനക്കാർക്കുള്ള പരിശീലനം',
      'intro' => '<p>ജിദ്ദ വിനോദം, കോർപ്പറേറ്റ്, ട്രാൻസിറ്റ് ഡിമാൻഡുകൾ കലർന്നതാണ്, ശക്തമായ ഫുഡ് ആൻഡ് ബിവറേജ് സംസ്കാരവും റെസ്റ്റോറന്റ് പലപ്പോഴും മുറികളേക്കാൾ തിരക്കേറിയ കോർണിഷ് ഹോട്ടൽ രീതിയും ഇവിടെയുണ്ട്.</p><h2>അത് പരിശീലനത്തിൽ വരുത്തുന്ന മാറ്റം</h2><p>ഇവിടെ ഫുഡ് ആൻഡ് ബിവറേജ് ആഴം പ്രധാനമാണ്. സേവന ക്രമം, ബാങ്ക്വറ്റ് പ്രവർത്തനങ്ങൾ, പാനീയ സേവനം, പോയിന്റ് ഓഫ് സെയിൽ അച്ചടക്കം എന്നിവ ഉയർന്ന തലത്തിൽ പരിശീലിപ്പിക്കുന്നു, ഔട്ട്‌ലെറ്റ് തിരക്ക് കാരണം അടുക്കള ടീമുകൾക്ക് അലർജൻ, താപനില നിയന്ത്രണ ഭാരവും കൂടുതലാണ്.</p><h2>കുടുംബ, ഗ്രൂപ്പ് സേവനം</h2><p>കുടുംബ ഇരിപ്പിടം, വലിയ സംഘങ്ങൾക്കുള്ള സേവനം, മജ്‌ലിസ് ശൈലിയിലുള്ള ക്രമീകരണങ്ങൾ എന്നിവ സാധാരണമാണ്, അതിനാൽ രണ്ടുപേർക്കുള്ള റെസ്റ്റോറന്റ് സാഹചര്യം അനുമാനിക്കുന്നതിന് പകരം ടേബിൾ സേവന പരിശീലനം ആ ലേഔട്ടുകൾ വ്യക്തമായി ഉൾക്കൊള്ളുന്നു.</p><h2>ടീമുകൾക്ക് സാധാരണയായി ഏറ്റവും കൂടുതൽ പിന്തുണ വേണ്ടിടം</h2><p>അതിഥികളെ തിരക്കുകൂട്ടാതെ ടേബിളുകൾ മാറ്റൽ, ഒരേ സമയം നടക്കുന്ന റെസ്റ്റോറന്റും ബാങ്ക്വറ്റും ഏകോപിപ്പിക്കൽ, ഔട്ട്‌ലെറ്റ് പൂർണ ശേഷിയിലായിരിക്കുമ്പോഴും ഭക്ഷ്യസുരക്ഷാ രേഖകൾ പൂർണമായി സൂക്ഷിക്കൽ.</p>',
    ),
    'hotel-training-makkah' => 
    array (
      'title' => 'മക്കയിലെ ഹോട്ടൽ ജീവനക്കാർക്കുള്ള പരിശീലനം',
      'intro' => '<p>മിക്ക പ്രോപ്പർട്ടികളും ഒരിക്കലും കാണാത്ത തോതിലും ടേൺഓവർ നിരക്കിലുമാണ് മക്കയിലെ ഹോട്ടലുകൾ പ്രവർത്തിക്കുന്നത്: വളരെ വലിയ മുറികളുടെ എണ്ണം, കാറുകളിലല്ല കോച്ചുകളിൽ അളക്കുന്ന ഗ്രൂപ്പ് വരവുകളും പുറപ്പെടലുകളും, മുഴുവൻ പ്രവർത്തന താളത്തെയും മാറ്റുന്ന സീസണൽ തിരക്കുകൾ.</p><h2>അത് പരിശീലനത്തിൽ വരുത്തുന്ന മാറ്റം</h2><p>വൻതോതിലുള്ള കൈകാര്യമാണ് പ്രധാന കഴിവ്. ഗ്രൂപ്പ് ചെക്ക്-ഇൻ, ചെക്ക്-ഔട്ട് നടപടിക്രമം, റൂം ബ്ലോക്കിംഗ്, നൂറുകണക്കിന് മുറികളിലുടനീളമുള്ള കീ നിയന്ത്രണം, വലിയ തോതിലുള്ള ഹൗസ്‌കീപ്പിംഗ് ടേൺഎറൗണ്ട് എന്നിവയ്ക്ക് വ്യക്തിഗത അതിഥി സേവനത്തേക്കാൾ പ്രാധാന്യമുണ്ട്.</p><h2>വലിയ തോതിലുള്ള ഹൗസ്‌കീപ്പിംഗ്</h2><p>റൂം ടേൺഎറൗണ്ട്, ഡീപ് ക്ലീനിംഗ് ചക്രങ്ങൾ, ലിനൻ കൈകാര്യ ശേഷി, ഉൽപ്പാദനക്ഷമതാ ആസൂത്രണം എന്നിവ ഒരു സംവിധാനമായി പരിശീലിപ്പിക്കുന്നു, കാരണം മോശമായി കൈകാര്യം ചെയ്ത ഒരു ഡിപ്പാർച്ചർ വേവ് അതേ ദിവസത്തിനുള്ളിൽ വീണ്ടെടുക്കില്ല.</p><h2>ടീമുകൾക്ക് സാധാരണയായി ഏറ്റവും കൂടുതൽ പിന്തുണ വേണ്ടിടം</h2><p>ഒരേ രാവിലെ ഒരു ഗ്രൂപ്പ് പുറപ്പെടലും ഗ്രൂപ്പ് വരവും ഏകോപിപ്പിക്കൽ, ടേൺഎറൗണ്ട് സമ്മർദ്ദത്തിലും മുറിയുടെ മാനദണ്ഡം നിലനിർത്തൽ, ടീമുമായി പൊതുവായ ഭാഷയൊന്നും പങ്കിടാത്തേക്കാവുന്ന അതിഥികളുമായി വ്യക്തമായ ബഹുഭാഷാ ആശയവിനിമയം.</p>',
    ),
    'hotel-training-madinah' => 
    array (
      'title' => 'മദീനയിലെ ഹോട്ടൽ ജീവനക്കാർക്കുള്ള പരിശീലനം',
      'intro' => '<p>മദീന മക്കയുടെ ഗ്രൂപ്പ് അധിഷ്ഠിത, ഉയർന്ന ടേൺഓവർ രീതി പങ്കിടുന്നു, പല പ്രോപ്പർട്ടികളിലും ശരാശരി താമസം കൂടുതലാണ്, ശാന്തവും തിരക്കില്ലാത്തതുമായ അതിഥി പരിചരണത്തിന് ശക്തമായ ഊന്നലുമുണ്ട്.</p><h2>അത് പരിശീലനത്തിൽ വരുത്തുന്ന മാറ്റം</h2><p>ഗ്രൂപ്പ് പ്രവർത്തനങ്ങൾ ഇപ്പോഴും പ്രബലമാണ്, പക്ഷേ സ്റ്റേഓവർ സേവനവും ദീർഘകാല താമസത്തിനുള്ള ഹൗസ്‌കീപ്പിംഗ് ക്രമങ്ങളും കൂടുതൽ പ്രധാനമാണ്, പ്രായമായതോ ചലനശേഷി കുറഞ്ഞതോ ആയ അതിഥിയെ ക്ഷമയോടെയും സ്വന്തം ഇഷ്ടപ്രകാരമല്ലാതെയും കൈകാര്യം ചെയ്യാനുള്ള കഴിവും.</p><h2>പ്രവേശനക്ഷമതയും സഹായവും</h2><p>റൂം അസൈൻമെന്റ് പരിശീലനം പ്രവേശനക്ഷമതാ ആവശ്യങ്ങൾ വ്യക്തമായി ഉൾക്കൊള്ളുന്നു, ഒഴിപ്പിക്കൽ സമയത്ത് ഉൾപ്പെടെ, ചലനശേഷി പരിമിതമായ അതിഥിയെ സഹായിക്കാൻ ഫ്രണ്ട് ഓഫീസ്, ഹൗസ്‌കീപ്പിംഗ് ടീമുകൾക്ക് പരിശീലനം നൽകുന്നു.</p><h2>ടീമുകൾക്ക് സാധാരണയായി ഏറ്റവും കൂടുതൽ പിന്തുണ വേണ്ടിടം</h2><p>ദീർഘകാല താമസ മുറിയെ മാനദണ്ഡത്തിൽ നിലനിർത്തുന്ന സ്റ്റേഓവർ സേവനം, ഭാഷാ തടസ്സത്തിനപ്പുറമുള്ള പരാതി കൈകാര്യം ചെയ്യൽ, ഫ്രണ്ട് ഓഫീസ്, ഹൗസ്‌കീപ്പിംഗ്, സെക്യൂരിറ്റി എന്നിവയ്ക്കിടയിൽ സഹായ അഭ്യർത്ഥനകൾ ഏകോപിപ്പിക്കൽ.</p>',
    ),
    'hotel-training-al-khobar' => 
    array (
      'title' => 'അൽ ഖോബാറിലെ ഹോട്ടൽ ജീവനക്കാർക്കുള്ള പരിശീലനം',
      'intro' => '<p>അൽ ഖോബാറും ചുറ്റുമുള്ള കിഴക്കൻ പ്രവിശ്യാ ഇടനാഴിയും സ്ഥിരമായ വ്യാവസായിക, കോർപ്പറേറ്റ് വിപണിക്ക് സേവനം നൽകുന്നു, പരമ്പരാഗത ബിസിനസ് യാത്രയ്ക്കൊപ്പം കരാറുകാർക്കുള്ള ദീർഘകാല താമസ സൗകര്യവുമുണ്ട്.</p><h2>അത് പരിശീലനത്തിൽ വരുത്തുന്ന മാറ്റം</h2><p>ദീർഘകാല താമസ പ്രവർത്തനങ്ങൾ പ്രധാനമാണ്: സ്റ്റേഓവർ സേവന ക്രമങ്ങൾ, നീണ്ട താമസത്തിനുള്ള ലിനൻ മാറ്റ ആവൃത്തി, കമ്പനി കരാർ നിരക്കുകളുടെയും ബില്ലിംഗിന്റെയും സ്ഥിരമായ കൈകാര്യം.</p><h2>എഞ്ചിനീയറിംഗ് ഭാരം</h2><p>ദീർഘകാലം ഉയർന്ന ഒക്യുപൻസി തേയ്മാനം വർദ്ധിപ്പിക്കുന്നു, അതിനാൽ പ്രിവന്റീവ് മെയിന്റനൻസ് ഷെഡ്യൂളിംഗ്, HVAC ക്രമങ്ങൾ, വർക്ക് ഓർഡർ അച്ചടക്കം എന്നിവ കുറഞ്ഞ ഒക്യുപൻസിയുള്ള വിനോദ പ്രോപ്പർട്ടിയേക്കാൾ കൂടുതൽ പരിശീലിപ്പിക്കുന്നു.</p><h2>ടീമുകൾക്ക് സാധാരണയായി ഏറ്റവും കൂടുതൽ പിന്തുണ വേണ്ടിടം</h2><p>ദീർഘകാല താമസ മുറിയെ വരവിന്റെ മാനദണ്ഡത്തിൽ നിലനിർത്തൽ, ആഴ്ചകളോളം കോർപ്പറേറ്റ് ബില്ലിംഗ് കൃത്യമായി കൈകാര്യം ചെയ്യൽ, സ്ഥിരമായി നിറഞ്ഞ ഇൻവെന്ററിയിൽ നിന്ന് മുറികൾ ഒഴിവാക്കാതെ പ്രിവന്റീവ് മെയിന്റനൻസ് നടത്തൽ.</p>',
    ),
    'hotel-training-dammam' => 
    array (
      'title' => 'ദമ്മാമിലെ ഹോട്ടൽ ജീവനക്കാർക്കുള്ള പരിശീലനം',
      'intro' => '<p>ദമ്മാമിലെ പ്രോപ്പർട്ടികൾ, പ്രത്യേകിച്ച് വിമാനത്താവളത്തിന് സമീപമുള്ളവ, ഇരുപത്തിനാല് മണിക്കൂറിലുടനീളം വ്യാപിച്ചിരിക്കുന്ന വരവുകളും പുറപ്പെടലുകളുമായി ചെറുതും ട്രാൻസിറ്റുമായ താമസങ്ങളുടെ ഉയർന്ന പങ്ക് കൈകാര്യം ചെയ്യുന്നു.</p><h2>അത് പരിശീലനത്തിൽ വരുത്തുന്ന മാറ്റം</h2><p>നൈറ്റ് ഷിഫ്റ്റ് കഴിവ് ഐച്ഛികമല്ല. നൈറ്റ് ഓഡിറ്റ്, രാത്രിയിലെ ചെക്ക്-ഇൻ, വൈകി എത്തുന്നവരെ കൈകാര്യം ചെയ്യൽ, പകൽ മാനേജർ ഇല്ലാതെ പ്രോപ്പർട്ടി പ്രവർത്തിപ്പിക്കാനാകുന്ന നൈറ്റ് ടീം എന്നിവയെല്ലാം വിപുലമായതല്ല, അടിസ്ഥാനപരമാണ്.</p><h2>വേഗത്തിലുള്ള ടേൺഎറൗണ്ട്</h2><p>ചെറിയ താമസങ്ങൾ എന്നാൽ ഓരോ മുറിക്കും മാസത്തിൽ കൂടുതൽ പുറപ്പെടലുകൾ, അതിനാൽ ഹൗസ്‌കീപ്പിംഗ് ടേൺഎറൗണ്ട് വേഗതയ്ക്കും ഫ്രണ്ട് ഓഫീസ് ഡിപ്പാർച്ചർ പ്രോസസ്സിംഗിനും ദീർഘകാല താമസ ക്രമങ്ങളേക്കാൾ പ്രാധാന്യമുണ്ട്.</p><h2>ടീമുകൾക്ക് സാധാരണയായി ഏറ്റവും കൂടുതൽ പിന്തുണ വേണ്ടിടം</h2><p>ചെറിയ ടീമുമായി കാര്യക്ഷമമായ നൈറ്റ് ഷിഫ്റ്റ് നടത്തൽ, സാധാരണ ചെക്ക്-ഇൻ സമയത്തിന് മുമ്പുള്ള അതിരാവിലെയുള്ള വരവ് കൈകാര്യം ചെയ്യൽ, ഉയർന്ന ടേൺഎറൗണ്ട് നിരക്കിലും മുറിയുടെ മാനദണ്ഡം നിലനിർത്തൽ.</p>',
    ),
    'hotel-training-alula' => 
    array (
      'title' => 'അൽഉലയിലെ ഹോട്ടൽ ജീവനക്കാർക്കുള്ള പരിശീലനം',
      'intro' => '<p>അൽഉലയിലെ പ്രോപ്പർട്ടികൾ റിസോർട്ട്, അനുഭവ കേന്ദ്രീകൃതമാണ്, പലപ്പോഴും കുറഞ്ഞ മുറികളും, കൂടുതൽ നീണ്ട വിനോദ താമസങ്ങളും, ഈ ലക്ഷ്യസ്ഥാനത്തിനായി പ്രത്യേകം യാത്ര ചെയ്തെത്തിയ അതിഥിയുമാണ് ഇവിടെ.</p><h2>അത് പരിശീലനത്തിൽ വരുത്തുന്ന മാറ്റം</h2><p>കൺസിയേർജിനും പ്രാദേശിക അറിവിനും ഇവിടെ യഥാർത്ഥ പ്രാധാന്യമുണ്ട്, കാരണം ടീമിന് ലക്ഷ്യസ്ഥാനത്തെക്കുറിച്ച് അറിയാമെന്ന് അതിഥി പ്രതീക്ഷിക്കുന്നു. ഗസ്റ്റ് എക്സ്പീരിയൻസ്, വ്യക്തിഗതമാക്കൽ, പരാതി വീണ്ടെടുക്കൽ എന്നിവ കൈകാര്യ വേഗതയേക്കാൾ പ്രധാനമാണ്.</p><h2>ചെറിയ ടീമുകൾ, വിശാലമായ ചുമതലകൾ</h2><p>ചെറിയ പ്രോപ്പർട്ടി എന്നാൽ ഒരാൾ കൂടുതൽ മേഖലകൾ കൈകാര്യം ചെയ്യുന്നു, അതിനാൽ വകുപ്പുകൾക്കിടയിലുള്ള പരിശീലനം അപവാദമല്ല, സാധാരണമാണ്: ഒരു ഫ്രണ്ട് ഓഫീസ് ഏജന്റിന് ഫുഡ് ആൻഡ് ബിവറേജ് സേവന മാനദണ്ഡങ്ങളും അടിസ്ഥാന അടിയന്തര പ്രതികരണ നേതൃത്വവും ആവശ്യമായേക്കാം.</p><h2>ടീമുകൾക്ക് സാധാരണയായി ഏറ്റവും കൂടുതൽ പിന്തുണ വേണ്ടിടം</h2><p>മുഴുവൻ ടീമിനും ഉപയോഗിക്കാവുന്ന പ്രാദേശിക വിജ്ഞാന ശേഖരം തയ്യാറാക്കൽ, ഉയർന്ന പ്രതീക്ഷയുള്ള വിനോദ അതിഥിയെ കൈകാര്യം ചെയ്യൽ, ചെറിയ രാത്രി ടീമുമായി അടിയന്തര പ്രതികരണം നടത്തൽ.</p>',
    ),
    'hotel-training-abha' => 
    array (
      'title' => 'അബഹയിലെ ഹോട്ടൽ ജീവനക്കാർക്കുള്ള പരിശീലനം',
      'intro' => '<p>അബഹയും വിശാലമായ അസീർ മലനിരകളും ശക്തമായ സീസണൽ വിനോദ രീതിയിലാണ് പ്രവർത്തിക്കുന്നത്: വേനൽക്കാല തിരക്കുകൾ, കുടുംബ, ഗ്രൂപ്പ് ബുക്കിംഗുകളുടെ ഉയർന്ന അനുപാതം, സീസണനുസരിച്ച് ശേഷി തുറന്നേക്കാവുന്ന പ്രോപ്പർട്ടികൾ.</p><h2>അത് പരിശീലനത്തിൽ വരുത്തുന്ന മാറ്റം</h2><p>സീസണൽ റിക്രൂട്ട്മെന്റ് എന്നാൽ ചുരുങ്ങിയ അറിയിപ്പിൽ ചേരുന്നവർക്ക് പരിശീലനം ഫലപ്രദമാകണം. ദീർഘമായ വികസന പരിപാടികളേക്കാൾ നിർബന്ധിത സുരക്ഷാ പരിശീലനം, പ്രധാന വകുപ്പുതല ക്രമം, വ്യക്തമായ ഇൻഡക്ഷൻ എന്നിവ പ്രധാനമാണ്.</p><h2>കുടുംബ സേവനം</h2><p>കുടുംബ ബുക്കിംഗുകൾ റൂം അസൈൻമെന്റ്, ഹൗസ്‌കീപ്പിംഗ്, റെസ്റ്റോറന്റ് സേവനം എന്നിവയെ മാറ്റുന്നു, അതിനാൽ പരിശീലനം കണക്റ്റിംഗ് റൂമുകൾ, വലിയ സംഘങ്ങൾക്കുള്ള സേവനം, കുടുംബ ഇരിപ്പിടം എന്നിവ വ്യക്തമായി ഉൾക്കൊള്ളുന്നു.</p><h2>ടീമുകൾക്ക് സാധാരണയായി ഏറ്റവും കൂടുതൽ പിന്തുണ വേണ്ടിടം</h2><p>സീസണൽ ജീവനക്കാരെ വേഗത്തിൽ സുരക്ഷിതമായ മാനദണ്ഡത്തിലെത്തിക്കൽ, വേനൽക്കാല തിരക്കിലുടനീളം സേവന മാനദണ്ഡം നിലനിർത്തൽ, പ്രീ-ഓപ്പണിംഗ് അല്ലെങ്കിൽ സീസണൽ പുനരാരംഭത്തിനുള്ള മുറികളുടെ തയ്യാറെടുപ്പ്.</p>',
    ),
  ),
  'faq' => 
  array (
    'topic:front-office-training#8' => 
    array (
      'question' => 'ഒരു പുതിയ ഫ്രണ്ട് ഡെസ്ക് ഏജന്റ് ആദ്യം എന്താണ് പഠിക്കേണ്ടത്?',
      'answer' => 'ആദ്യം അഗ്നി സുരക്ഷയും പ്രോപ്പർട്ടി ഇൻഡക്ഷനും, തുടർന്ന് ഫ്രണ്ട് ഓഫീസ് അടിസ്ഥാനങ്ങളും ടെലിഫോൺ മര്യാദകളും, പിന്നെ ചെക്ക്-ഇൻ, ചെക്ക്-ഔട്ട്, അതിഥി രജിസ്ട്രേഷൻ, അതിനുശേഷം പ്രോപ്പർട്ടി മാനേജ്മെന്റ് സിസ്റ്റം. അടിസ്ഥാന ക്രമം സ്വാഭാവികമായിക്കഴിഞ്ഞാൽ പരാതി കൈകാര്യം ചെയ്യലും നൈറ്റ് ഓഡിറ്റും പിന്നീട് വരുന്നു.',
    ),
    'topic:housekeeping-training#9' => 
    array (
      'question' => 'ഒരു ഹോട്ടൽ മുറി വൃത്തിയാക്കാൻ എത്ര സമയമെടുക്കണം?',
      'answer' => 'ഒരു സാധാരണ ഡിപ്പാർച്ചർ ക്ലീനിന് സാധാരണയായി ഏകദേശം നാൽപ്പത് മിനിറ്റാണ് ലക്ഷ്യമിടുന്നത്, പക്ഷേ ഈ സംഖ്യ മുറിയുടെ വലുപ്പം, സൗകര്യങ്ങളുടെ നിലവാരം, പ്രോപ്പർട്ടി മാനദണ്ഡം എന്നിവയെ ആശ്രയിച്ചിരിക്കുന്നു. സമയം പ്രവചിക്കാവുന്നതാക്കുന്നത് ക്രമമാണ്: ഒരു നിശ്ചിത ക്രമത്തിൽ വൃത്തിയാക്കുന്നതാണ് മുറി കൂടുതൽ സമയമെടുക്കുന്നതും മോശമായി കാണുന്നതും തടയുന്നത്.',
    ),
    'topic:food-safety-training#10' => 
    array (
      'question' => 'ഹോട്ടലിൽ ചൂടുള്ള ഭക്ഷണം ഏത് താപനിലയിൽ സൂക്ഷിക്കണം?',
      'answer' => 'ചൂടുള്ള ഭക്ഷണം 63 ഡിഗ്രി സെൽഷ്യസിലോ അതിന് മുകളിലോ സൂക്ഷിക്കണം, ഹോൾഡിംഗ് താപനില ഓരോ രണ്ട് മണിക്കൂറിലും രേഖപ്പെടുത്തണം. പാകം ചെയ്ത ഭക്ഷണം സേവനത്തിന് മുമ്പ് 75 ഡിഗ്രി സെൽഷ്യസിലോ അതിന് മുകളിലോ എത്തണം, ശീതീകരിച്ച സംഭരണം 5 ഡിഗ്രി സെൽഷ്യസിലോ അതിന് താഴെയോ ആയിരിക്കണം.',
    ),
    'topic:hotel-sop-training#11' => 
    array (
      'question' => 'ഒരു ഹോട്ടൽ SOP എത്ര തവണ അവലോകനം ചെയ്യണം?',
      'answer' => 'പന്ത്രണ്ട് മാസത്തെ അവലോകന ഇടവേളയാണ് സാധാരണ സ്ഥിരക്രമം, ഓരോ നടപടിക്രമത്തിനും സ്വന്തം അവലോകന തീയതിയുണ്ട്. തടയാൻ പരാജയപ്പെട്ട ഏതൊരു സംഭവത്തിനും ശേഷവും, അത് ആശ്രയിക്കുന്ന ഉപകരണം, സിസ്റ്റം അല്ലെങ്കിൽ നിയന്ത്രണം മാറുമ്പോഴും നടപടിക്രമം ഉടൻ അവലോകനം ചെയ്യണം.',
    ),
    'global:#0' => 
    array (
      'question' => 'എന്താണ് Hospitality Academy?',
      'answer' => 'Hospitality Academy ഒരു ഹോട്ടൽ പരിശീലന, സ്റ്റാൻഡേർഡ് ഓപ്പറേറ്റിംഗ് പ്രൊസീജർ പ്ലാറ്റ്ഫോമാണ്. ഇത് ഹോട്ടൽ വകുപ്പുകൾക്കായി റോൾ അധിഷ്ഠിത കോഴ്സുകൾ, പതിപ്പുകളുള്ള SOP ലൈബ്രറി, മൂല്യനിർണയങ്ങൾ, പൊതുവായി സ്ഥിരീകരിക്കാവുന്ന സർട്ടിഫിക്കറ്റുകൾ എന്നിവ നൽകുന്നു. കോഴ്സുകൾ അറബിയിലും ഇംഗ്ലീഷിലും ലഭ്യമാണ്.',
    ),
    'global:#1' => 
    array (
      'question' => 'കോഴ്സുകൾ അറബിയിൽ ലഭ്യമാണോ?',
      'answer' => 'ഉവ്വ്. ഓരോ കോഴ്സും പാഠവും നടപടിക്രമവും പൊതു പേജും വെവ്വേറെ എഴുതിയ ഉള്ളടക്കമായി അറബിയിലും ഇംഗ്ലീഷിലും ലഭ്യമാണ്, അറബി ഇന്റർഫേസ് ഇംഗ്ലീഷിന്റെ പ്രതിബിംബമല്ല, യഥാർത്ഥ വലത്തുനിന്ന് ഇടത്തോട്ടുള്ള ലേഔട്ടാണ് ഉപയോഗിക്കുന്നത്.',
    ),
    'global:#2' => 
    array (
      'question' => 'ഒരു Hospitality Academy സർട്ടിഫിക്കറ്റ് എങ്ങനെ സ്ഥിരീകരിക്കാം?',
      'answer' => 'സർട്ടിഫിക്കറ്റിൽ അച്ചടിച്ചിരിക്കുന്ന സ്ഥിരീകരണ കോഡ് പൊതു സ്ഥിരീകരണ പേജിൽ നൽകുക. പേജ് നാല് ഫലങ്ങളിൽ ഒന്ന് നേരിട്ട് നൽകുന്നു: സാധുവായത്, കാലാവധി കഴിഞ്ഞത്, റദ്ദാക്കിയത്, അല്ലെങ്കിൽ കണ്ടെത്തിയില്ല. സർട്ടിഫിക്കറ്റ് പരിശോധിക്കാൻ അക്കൗണ്ട് ആവശ്യമില്ല.',
    ),
    'global:#3' => 
    array (
      'question' => 'ഒരു ഹോട്ടൽ പരിശീലന കോഴ്സിന് എത്ര സമയമെടുക്കും?',
      'answer' => 'മിക്ക കോഴ്സുകൾക്കും നാൽപ്പത്തഞ്ച് മിനിറ്റ് മുതൽ മൂന്ന് മണിക്കൂർ വരെ പഠനം ആവശ്യമാണ്, ഇത് പല ഷിഫ്റ്റുകളിലായി വിഭജിക്കാം. ഓരോ കോഴ്സ് പേജും അതിന്റെ ദൈർഘ്യം വ്യക്തമാക്കുന്നു, പുരോഗതി സേവ് ചെയ്യപ്പെടുന്നതിനാൽ പഠിതാവിന് നിർത്തി പിന്നീട് തുടരാം.',
    ),
    'global:#4' => 
    array (
      'question' => 'ഒരു ഹോട്ടലിന് ഒരു മുഴുവൻ വകുപ്പിനും ഒരേസമയം പരിശീലനം നൽകാനാകുമോ?',
      'answer' => 'ഉവ്വ്. ഒരു പരിശീലന അസൈൻമെന്റ് ഒരു വ്യക്തി, വകുപ്പ്, പ്രോപ്പർട്ടി, ജോലി റോൾ അല്ലെങ്കിൽ മുഴുവൻ സ്ഥാപനത്തെയും ലക്ഷ്യമിടാം; ആരംഭ തീയതി, പൂർത്തീകരണ തീയതി, സമയപരിധിക്ക് മുമ്പുള്ള ഓർമ്മപ്പെടുത്തലുകൾ, ഒരു ഇനം കാലാവധി കഴിയുമ്പോൾ ലൈൻ മാനേജറിലേക്കുള്ള എസ്കലേഷൻ എന്നിവയോടെ.',
    ),
    'global:#5' => 
    array (
      'question' => 'എന്താണ് ഹോട്ടൽ SOP?',
      'answer' => 'ഹോട്ടൽ SOP അഥവാ സ്റ്റാൻഡേർഡ് ഓപ്പറേറ്റിംഗ് പ്രൊസീജർ, ഒരു ജോലി എങ്ങനെ കൃത്യമായി നിർവഹിക്കണമെന്ന് വ്യക്തമാക്കുന്ന രേഖയാണ്: അതിന്റെ ഉദ്ദേശ്യം, വ്യാപ്തി, ഉത്തരവാദിത്തങ്ങൾ, ആവശ്യമായ ഉപകരണങ്ങൾ, നമ്പറിട്ട ഘട്ടങ്ങൾ, ചെക്ക്‌ലിസ്റ്റ്, സുരക്ഷാ കുറിപ്പുകൾ, ഗുണനിലവാര മാനദണ്ഡം, എസ്കലേഷൻ മാർഗം. ഏത് തീയതിയിലും ഏത് പതിപ്പാണ് പ്രാബല്യത്തിലുണ്ടായിരുന്നതെന്ന് ഹോട്ടലിന് തെളിയിക്കാനാകുന്ന വിധം ഇതിന് ഒരു പതിപ്പ് നമ്പറുണ്ട്.',
    ),
    'global:#6' => 
    array (
      'question' => 'അക്കാദമി വിജയ നിരക്കുകളോ വിജയ സ്ഥിതിവിവരക്കണക്കുകളോ പ്രസിദ്ധീകരിക്കുന്നുണ്ടോ?',
      'answer' => 'ഇല്ല. സന്ദർശകന് മുന്നിൽ തെളിവ് നൽകാനാകാത്ത അവകാശവാദങ്ങളായതിനാൽ അക്കാദമി വിജയ നിരക്കുകളോ തൊഴിലുടമകളുടെ അംഗീകാരങ്ങളോ അക്രഡിറ്റേഷൻ അവകാശവാദങ്ങളോ പ്രസിദ്ധീകരിക്കുന്നില്ല. ഒരു സർട്ടിഫിക്കറ്റ് അത് രേഖപ്പെടുത്തുന്നത് മാത്രം പ്രസ്താവിക്കുന്നു: ആര് എന്ത് പൂർത്തിയാക്കി, എപ്പോൾ, ഏത് സ്കോറോടെ, അത് ഇപ്പോഴും സാധുവാണോ എന്ന്.',
    ),
    'global:#7' => 
    array (
      'question' => 'ഓരോ ഹോട്ടൽ ജീവനക്കാരനും നിർബന്ധമായ പരിശീലനം ഏതാണ്?',
      'answer' => 'അഗ്നി സുരക്ഷ, അടിയന്തര പ്രതികരണം, പ്രോപ്പർട്ടി ഇൻഡക്ഷൻ എന്നിവ വകുപ്പ് ഏതായാലും ഓരോ ജീവനക്കാരനും നൽകുന്നു, സാധാരണയായി ജോലിയിൽ ചേർന്ന തീയതി മുതൽ ഏഴ് ദിവസത്തെ പൂർത്തീകരണ തീയതിയോടെ. ആ അപകടസാധ്യതകൾ കൈകാര്യം ചെയ്യുന്ന റോളുകൾക്ക് രാസവസ്തു സുരക്ഷ, ഭക്ഷ്യസുരക്ഷ, കത്തി സുരക്ഷ എന്നിവ നിർബന്ധമാണ്.',
    ),
